/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A28: ectotherm–elude (80-lemma frozen manifest; checkpoint 1/4). */
'use strict';
const D = globalThis.RA.D;
const q = (w,n,s,prompt,options,answer,explain) => ({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt,options,answer,explain});
const c = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const put = (w,origin,context,wrong,right,reason,quizOrType,maybeQuiz) => { const quiz=Array.isArray(quizOrType)?quizOrType:maybeQuiz; const errorType=Array.isArray(quizOrType)?'meaning':quizOrType; D(w,{etymology:{origin,source:'conservative word-history note'},contexts:[context],mistakes:[{errorType,wrong,right,reason}],quiz}); };

put('ectotherm','ectotherm 由希腊语词素 ecto-“外部”和 therm-“热”构成，指主要依赖环境取得体热的动物。',c('ectotherm.s1','动物生理','On a cool morning, the ectotherm stayed motionless on a sunlit rock until its body warmed enough for it to hunt.','凉爽的早晨，这只外温动物一直静卧在阳光照射的石头上，直到身体暖到足以捕猎。','On a cool morning / the ectotherm stayed motionless on a sunlit rock / until its body warmed enough for it to hunt.','ectotherm 是 stayed 的主语；until 从句说明它何时恢复活动。','依靠日照升温而后活动，体现 ectotherm 对环境热量的依赖。'),'The ectotherm kept a stable body temperature by generating all its heat internally, whatever the weather.','The endotherm kept a stable body temperature by generating most of its heat internally.','外温动物依赖环境供热；主要靠自身代谢维持体温的是内温动物。',[q('ectotherm',1,1,'Which animal is an ectotherm?',['a lizard that warms itself on a rock','a mammal that maintains heat through metabolism','a bird whose feathers insulate its body'],'a lizard that warms itself on a rock','ectotherm 主要从外界获取体热。'),q('ectotherm',2,1,'Why might an ectotherm bask in sunlight?',['to raise its body temperature using external heat','to manufacture sunlight inside its muscles','to keep its body warmer than the sun'],'to raise its body temperature using external heat','晒太阳可利用外部热源升温。'),q('ectotherm',3,1,'A cold ectotherm often becomes less active because?',['its body functions depend partly on environmental warmth','it has too many feathers','it produces heat at a constant high rate'],'its body functions depend partly on environmental warmth','环境降温会影响外温动物的身体活动。'),q('ectotherm',4,1,'The element ecto- in ectotherm means?',['outside','equal','underwater'],'outside','ecto- 表示外部；therm 与热有关。')]);

put('ectothermic','ectothermic 由 ecto-“外部”、therm“热”及形容词后缀 -ic 组成，指体热主要来自环境的。',c('ectothermic.s1','爬行动物','Because the snake is ectothermic, its keeper provides a warm lamp at one end of the enclosure and a cooler retreat at the other.','由于这条蛇是外温动物，饲养者在围栏一端提供加热灯，在另一端留出较凉的躲避处。','Because the snake is ectothermic / its keeper provides a warm lamp at one end of the enclosure / and a cooler retreat at the other.','ectothermic 作表语形容词；because 从句给出设置温度梯度的原因。','外温蛇需借助外界热源，暖区和凉区供其调节体温。'),'The ectothermic snake generated enough internal heat to remain equally warm in every environment.','The endothermic animal generated enough internal heat to remain warm in varied environments.','ectothermic 描述依赖环境热量，句中却说它自身持续产热。','meaning',[q('ectothermic',1,1,'An ectothermic animal relies mainly on?',['heat from its surroundings','a constant internal furnace','electricity from a battery'],'heat from its surroundings','ectothermic.s1 指依靠外部热源。'),q('ectothermic',2,1,'Why provide a temperature gradient for an ectothermic reptile?',['it can move between warmer and cooler areas','it must keep every part of its enclosure at freezing','it cannot sense any change in temperature'],'it can move between warmer and cooler areas','外温动物通过改变位置调节体温。'),q('ectothermic',3,1,'Which observation fits an ectothermic lizard?',['it becomes more active after basking','it stays equally warm without regard to surroundings','it produces feathers in winter'],'it becomes more active after basking','晒暖后活动增强符合外温特性。'),q('ectothermic',4,1,'Which term is closest in meaning to ectothermic?',['dependent on external heat','powered by internal metabolic heat','unable to absorb heat'],'dependent on external heat','外温指热量依赖外部来源。')]);

put('eddy','eddy 的词源史不完全确定，现代英语中作名词指逆着主流方向打旋的气流或水流，也作动词表示盘旋。',c('eddy.s1','河流观察','Leaves gathered in an eddy behind the bridge pier, circling slowly before the current carried them downstream.','树叶聚在桥墩后方的回流涡中，缓慢打转，随后被水流带向下游。','Leaves gathered in an eddy behind the bridge pier / circling slowly / before the current carried them downstream.','eddy 作介词 in 的宾语，指水流形成的旋涡；circling 补充运动状态。','桥墩后逆主流转圈的水流是 eddy.s1。'),'The boat crossed an eddy where the water moved in a perfectly straight line with the main current.','The boat crossed a smooth stretch where the water moved in a straight line with the main current.','eddy 必须有打旋的回流特征；直线顺流不是旋涡。',[q('eddy',1,1,'An eddy in a stream is a patch of water that?',['circles against or beside the main current','flows only in a straight line','has become solid ice'],'circles against or beside the main current','eddy.s1 是水流中的旋涡。'),q('eddy',2,2,'If smoke eddies through an open doorway, it?',['swirls as it moves','freezes into a block','disappears without moving'],'swirls as it moves','eddy 作动词表示打旋、盘旋。'),q('eddy',3,1,'Where might a small eddy form in a river?',['behind a rock that disrupts the current','in a perfectly still sealed bottle','on a dry hillside with no air movement'],'behind a rock that disrupts the current','障碍物后方容易形成回流涡。'),q('eddy',4,1,'A leaf trapped in an eddy will most likely?',['circle for a while before escaping','sink through the riverbed instantly','travel in a straight line at once'],'circle for a while before escaping','旋涡可使漂浮物暂时绕圈。')]);

put('edentate','edentate 源自拉丁语 edentatus，由 e-“无”与 dens“牙齿”构成；可描述无齿的动物，也可作名词指贫齿类动物。',c('edentate.s1','哺乳动物学','The fossil was classified as an edentate because its jaws lacked teeth, a feature shared by some living sloths and anteaters.','这块化石被归为贫齿类，因为其颌骨没有牙齿；一些现存树懒和食蚁兽也有这种特征。','The fossil was classified as an edentate / because its jaws lacked teeth / a feature shared by some living sloths and anteaters.','edentate 作名词，作 classified as 的表语；because 从句说明分类依据。','无齿颌骨与所举动物特征对应贫齿义。'),'The edentate fossil had a full set of sharp teeth in both jaws.','The toothed fossil had a full set of sharp teeth in both jaws.','edentate 指无齿或属于贫齿类；满口利齿与该描述直接相反。','meaning',[q('edentate',1,1,'An edentate animal is described as?',['having no teeth or belonging to a tooth-poor group','having an unusually large set of teeth','being a type of flowering plant'],'having no teeth or belonging to a tooth-poor group','edentate 的构词和词义都与无齿相关。'),q('edentate',2,1,'Which animals are classically associated with edentates?',['sloths and anteaters','sharks and dolphins','eagles and owls'],'sloths and anteaters','贫齿类传统分类包括树懒、食蚁兽等。'),q('edentate',3,1,'A zoologist calls a specimen edentate after finding?',['toothless jaws','a bright feathered tail','a shell made of iron'],'toothless jaws','无齿颌骨支持 edentate 的判断。'),q('edentate',4,1,'The Latin element dent in edentate relates to?',['teeth','water','light'],'teeth','dent- 与牙齿有关，e- 表示缺少。')]);

put('edibility','edibility 由 edible“可食的”加名词后缀 -ity 构成，表示某物是否适合食用的性质。',c('edibility.s1','野外采集','Before serving the unfamiliar mushroom, the botanist checked reliable regional records of its edibility rather than relying on its pleasant smell.','在端上这种不熟悉的蘑菇之前，植物学家查阅了可靠的当地可食性资料，而没有只凭气味判断。','Before serving the unfamiliar mushroom / the botanist checked reliable regional records of its edibility / rather than relying on its pleasant smell.','edibility 是介词 of 的宾语；rather than 对比可靠证据与不充分的嗅觉判断。','查证能否安全食用，正是 edibility。'),'The guide judged the mushroom’s edibility by how brightly it glowed in the dark.','The guide judged the mushroom’s visibility by how brightly it glowed in the dark.','发光与否不能证明蘑菇适不适合食用。','meaning',[q('edibility',1,1,'A test of a plant’s edibility asks whether it is?',['safe and suitable to eat','easy to photograph','likely to grow in shade'],'safe and suitable to eat','edibility 表示可食性。'),q('edibility',2,1,'Which evidence best supports a claim about a wild berry’s edibility?',['reliable identification and safety data','its attractive color alone','the fact that birds are nearby'],'reliable identification and safety data','辨认种类并查证安全资料更可靠。'),q('edibility',3,1,'A food scientist studying edibility would focus on?',['whether people can eat the item safely','how loudly it can be heard','how quickly it can be painted'],'whether people can eat the item safely','可食性关注能否食用。'),q('edibility',4,1,'Edibility is the noun related to which adjective?',['edible','edibly','editorial'],'edible','edibility 由 edible 加名词后缀构成。')]);

put('edifice','edifice 经古法语 edifice 源自拉丁语 aedificium“建筑物”，最终与 aedificare“建造”有关；常指宏伟或庄严的大建筑。',c('edifice.s1','城市建筑','The courthouse was an imposing stone edifice with a broad staircase and columns that dominated the small square.','法院是一座气势恢宏的石砌大厦，宽阔的台阶和柱廊俯视着小广场。','The courthouse was an imposing stone edifice / with a broad staircase and columns / that dominated the small square.','edifice 作 was 的表语名词；with 短语描写建筑特征。','宏大、庄严的法院建筑符合 edifice 的常见语气。'),'The hikers called the tiny paper tent an edifice that filled the entire valley.','The hikers called the towering stone hall an edifice that filled the entire valley.','edifice 通常指大型、醒目的建筑；轻便小帐篷不合此语境。','meaning',[q('edifice',1,1,'An imposing edifice is a?',['large and impressive building','small handwritten note','temporary gust of wind'],'large and impressive building','edifice 指建筑物，常带宏伟、庄严意味。'),q('edifice',2,1,'Which might a visitor describe as an edifice?',['a monumental city hall','a single brick used in a wall','a spoken greeting'],'a monumental city hall','宏大的市政厅适合称作 edifice。'),q('edifice',3,1,'The word edifice is most naturally used for?',['a substantial structure','a person’s brief comment','a narrow strip of paper'],'a substantial structure','edifice 不是小物件或言语，而是建筑。'),q('edifice',4,1,'A historic edifice would most likely be?',['a notable building preserved for its architecture','a new pair of shoes','a cloud formation'],'a notable building preserved for its architecture','历史性建筑符合 edifice 的名词义。')]);

put('edify','edify 经古法语 edifier 源自拉丁语 aedificare“建造”，后发展出以知识或品格“建造”人的比喻义，表示启迪、教益。',c('edify.s1','阅读教育','The museum designed its audio guide to edify visitors about the city’s migration history without turning the tour into a lecture.','博物馆设计语音导览，旨在让参观者了解这座城市的移民史，同时避免把参观变成说教。','The museum designed its audio guide / to edify visitors about the city’s migration history / without turning the tour into a lecture.','edify 带宾语 visitors；不定式说明设计导览的目的。','导览使人增长知识，体现 edify 的启迪义。'),'The guide tried to edify visitors by hiding every historical fact from them.','The guide tried to confuse visitors by hiding every historical fact from them.','隐瞒信息会妨碍启迪学习，而不是 edify。','meaning',[q('edify',1,1,'To edify an audience is to?',['instruct or improve them intellectually or morally','prevent them from learning','decorate the room they occupy'],'instruct or improve them intellectually or morally','edify 指教益、启迪。'),q('edify',2,1,'Which activity could edify museum visitors?',['an exhibit that explains the evidence behind an event','a display with labels deliberately removed','a room kept dark with no information'],'an exhibit that explains the evidence behind an event','解释证据的展览能使参观者增长知识。'),q('edify',3,1,'Edify is closest to which verb in this context?',['enlighten','mislead','erase'],'enlighten','启迪、教益与 enlighten 意义接近。'),q('edify',4,1,'A speaker gives an edifying talk when it?',['offers useful insight and instruction','contains no meaningful information','consists only of unrelated noises'],'offers useful insight and instruction','有教益的演讲提供知识或见解。')]);

put('editor','editor 经古法语 editeur 源自拉丁语 editor“出版者”，与 edere“发表、出版”有关；可指负责编辑内容的人，也可指编辑软件。',c('editor.s1','出版工作','The editor returned the draft with questions in the margins, asking the author to verify two dates and clarify the final paragraph.','编辑把稿件退回，并在页边写下问题，要求作者核实两个日期并澄清最后一段。','The editor returned the draft with questions in the margins / asking the author to verify two dates / and clarify the final paragraph.','editor 是 returned 的主语；现在分词短语说明编辑提出的要求。','核对事实、修改表达是内容编辑的工作，对应 editor.s1。'),'The editor repaired the leaking roof while the electrician corrected the article’s punctuation.','The building caretaker repaired the leaking roof while the editor corrected the article’s punctuation.','编辑负责文本内容；修屋顶通常是维修人员的工作。','meaning',[q('editor',1,1,'A book editor usually helps to?',['revise and prepare a manuscript for publication','print money at a bank','repair a road surface'],'revise and prepare a manuscript for publication','editor.s1 指编辑作品的人。'),q('editor',2,2,'A video editor is a program that lets a user?',['cut, arrange, and alter video clips','measure blood pressure with a cuff','grow plants in soil'],'cut, arrange, and alter video clips','editor.s2 指用于编辑内容的软件。'),q('editor',3,1,'Why might an editor query a date in a draft?',['to check factual accuracy before publication','to make the date less readable','to replace every paragraph with a picture'],'to check factual accuracy before publication','核查日期是编辑工作的一部分。'),q('editor',4,1,'Which person is most likely the editor of a newspaper?',['the person who reviews and shapes its articles','a reader who only buys one copy','the driver who delivers paper rolls'],'the person who reviews and shapes its articles','审阅和编排文章的人是编辑。')]);

put('educable','educable 由 educate 加形容词后缀 -able 构成，意为能够通过教学而学习；描述学习潜力，不等于已经受过教育。',c('educable.s1','学习发展','The assessment showed that the child was educable when instruction was broken into short, carefully modelled steps.','评估显示，只要把教学拆成简短且有示范的步骤，这个孩子就能够学习。','The assessment showed that the child was educable / when instruction was broken into short / carefully modelled steps.','educable 作表语形容词；when 从句说明学习能力发挥的条件。','在适当教学下能够学习，正是 educable.s1。'),'The report called the student educable because no instruction could ever help the student learn.','The report called the student unteachable because no instruction could help the student learn.','educable 表示具备可教、可学的能力；无法受教与之相反。','meaning',[q('educable',1,1,'An educable person is?',['capable of learning through instruction','unable to learn anything','already a professional teacher'],'capable of learning through instruction','educable.s1 表示能够受教并学习。'),q('educable',2,1,'Which observation supports calling a pupil educable?',['the pupil learns a skill with suitable teaching','the pupil is never given a chance to practise','the pupil refuses every form of communication'],'the pupil learns a skill with suitable teaching','在合适教学下取得学习进展体现可教性。'),q('educable',3,1,'The suffix -able in educable contributes the sense?',['able to be taught','one who teaches','the act of teaching'],'able to be taught','-able 常表示“能够……的”。'),q('educable',4,1,'Educable describes a person’s?',['capacity to learn','current job title','country of birth'],'capacity to learn','educable 说的是学习潜力，不是职业或籍贯。')]);

put('educated','educated 是 educate 的过去分词形容词；educate 经拉丁语 educare“培养、教养”而来，表示受过教育，也可指见多识广。',c('educated.s1','公共讨论','An educated reader can question a confident claim, compare the evidence, and still recognize where personal expertise ends.','受过良好教育的读者能够质疑看似肯定的说法、比较证据，同时也明白个人专长的边界。','An educated reader can question a confident claim / compare the evidence / and still recognize where personal expertise ends.','educated 修饰 reader；can 后并列三个动词，概括知识和判断力。','批判性阅读和承认知识边界体现受教育、见多识广。'),'An educated engineer ignored every measurement and relied only on a lucky guess.','An untrained guesser ignored every measurement and relied only on luck.','educated 在此含有受过学习训练、具备知识判断力的意思；盲目猜测不能体现它。','meaning',[q('educated',1,1,'An educated response to a claim would be based on?',['knowledge and considered judgment','a guess made without evidence','the loudest voice in the room'],'knowledge and considered judgment','educated 可指受教育且有知识判断力。'),q('educated',2,1,'Which person is clearly educated in a subject?',['someone who has studied it and understands its evidence','someone who has never encountered it','someone who memorizes one unrelated word'],'someone who has studied it and understands its evidence','学习并理解证据表明具备相关知识。'),q('educated',3,1,'An educated estimate is most likely?',['informed by relevant facts','chosen by rolling dice','made without looking at any data'],'informed by relevant facts','educated estimate 是有依据、有知识的估计。'),q('educated',4,1,'In “an educated audience,” educated most nearly means?',['knowledgeable and informed','expensive to entertain','unable to read'],'knowledgeable and informed','此处 educated 可表示见多识广。')]);

put('education','education 由 educate 加名词后缀 -ion 构成；educate 经拉丁语 educare“培养、教养”而来，可指教学学习过程，也可指教育学或系统训练。',c('education.s1','学校制度','The new education policy requires schools to give every pupil access to qualified teachers, accessible materials, and time for guided practice.','新的教育政策要求学校让每个学生都能获得合格教师、易获取的教材和有指导的练习时间。','The new education policy requires schools / to give every pupil access to qualified teachers / accessible materials / and time for guided practice.','education 作定语修饰 policy；require 后接宾语加不定式结构。','学校、教师和学习资源的安排属于教育事业与教学过程。'),'The district improved education by removing teachers, lessons, and learning materials from every school.','The district weakened education by removing teachers, lessons, and learning materials from every school.','撤走教学人员、课程和材料会损害教育，不会改善教育。','meaning',[q('education',1,1,'Education in a school district mainly concerns?',['organized teaching and learning','the design of highway bridges','the manufacture of kitchen knives'],'organized teaching and learning','education.s1 指教学和学习过程。'),q('education',2,2,'A student studying education at university may focus on?',['how teaching and learning are organized','how to extract metal from ore','how to navigate a ship at sea'],'how teaching and learning are organized','education.s2 指教育学。'),q('education',3,1,'Which change would most directly expand access to education?',['providing trained teachers and learning materials','closing every classroom','withholding lessons from beginners'],'providing trained teachers and learning materials','师资与材料能支持更多人接受教育。'),q('education',4,1,'A broad education can help a person?',['develop knowledge and skills across subjects','avoid learning any new ideas','forget how to read'],'develop knowledge and skills across subjects','教育能帮助人形成知识与技能。')]);

put('educationally','educationally 由 educational 加副词后缀 -ly 构成，表示从教育角度、就学习效果而言；不等同于“情绪上”或“经济上”。',c('educationally.s1','课程评估','The museum’s short film was educationally useful because it connected the fossil display to evidence pupils could examine themselves.','博物馆的短片具有教育价值，因为它把化石展品与学生能够亲自观察的证据联系起来。','The museum’s short film was educationally useful / because it connected the fossil display / to evidence pupils could examine themselves.','educationally 修饰 useful，说明评价维度；because 引出学习价值的依据。','短片帮助学生学习并检验证据，属于教育效果。'),'The lesson was educationally successful because the classroom paint was inexpensive.','The lesson was economically inexpensive because the classroom paint was cheap.','墙面油漆价格属于经济因素，不能说明课程是否具有教育效果。','meaning',[q('educationally',1,1,'If a visit is educationally valuable, it?',['helps people learn','costs little money necessarily','makes everyone feel sad'],'helps people learn','educationally.s1 指从学习和教育角度有价值。'),q('educationally',2,1,'A museum label is educationally clear when it?',['helps visitors understand the exhibit','uses smaller print than anyone can read','contains unrelated advertising'],'helps visitors understand the exhibit','清晰解释展品有助于学习。'),q('educationally',3,1,'Which question evaluates a course educationally?',['What knowledge or skills did students gain?','What color are the chairs?','How many windows face east?'],'What knowledge or skills did students gain?','学习所得是教育效果的核心。'),q('educationally',4,1,'Educationally is related most directly to?',['teaching and learning','household income','physical distance'],'teaching and learning','educationally 来源于 educational，涉及教育。')]);

put('educator','educator 由 educate 加施事名词后缀 -or 构成；educate 经拉丁语 educare“培养、教养”而来，educator 指从事教育的人。',c('educator.s1','社区学习','The educator invited families to handle replica tools, then asked children to explain what each object might have been used for.','教育工作者邀请家庭成员触摸复制工具，随后请孩子们说明每件物品可能的用途。','The educator invited families to handle replica tools / then asked children / to explain what each object might have been used for.','educator 作主语；asked 后接宾语 children 和不定式补足语。','设计互动学习活动的人承担教育者角色。'),'The educator refused to teach anyone and spent the whole session selling train tickets.','The ticket agent refused to teach anyone and spent the whole session selling train tickets.','卖车票不是教育工作；educator 指教师或从事教育的人。','meaning',[q('educator',1,1,'An educator is someone whose work involves?',['teaching or supporting learning','repairing only electrical wires','selling tickets at a station'],'teaching or supporting learning','educator.s1 指教师或教育工作者。'),q('educator',2,1,'Which person is acting as an educator?',['a museum guide who helps visitors interpret exhibits','a cashier who only scans groceries','a mechanic replacing a tire'],'a museum guide who helps visitors interpret exhibits','帮助参观者学习和理解展品属于教育工作。'),q('educator',3,1,'A community educator might organize?',['a workshop on reading and health','a shipment of unlabelled bricks','a race without explaining the rules'],'a workshop on reading and health','组织学习活动是社区教育者的工作。'),q('educator',4,1,'The suffix -or in educator usually marks?',['a person who performs an action','a place where water collects','a quality of being blue'],'a person who performs an action','-or 常构成表示施事者的名词。')]);

put('educe','educe 源自拉丁语 educere“引出、带出来”，由 ex-“向外”与 ducere“引导”构成；可指引出潜在信息，也可指从证据推断。',c('educe.s1','文本分析','From the repeated references to winter, the critic educed a pattern of loss that the narrator never states directly.','评论者从反复出现的冬季意象中推断出一种叙述者从未直接说出的失落模式。','From the repeated references to winter / the critic educed a pattern of loss / that the narrator never states directly.','educe 作及物动词，宾语为 a pattern；that 从句修饰 pattern。','评论者根据重复线索推断潜在主题，体现 educe.s1。'),'The analyst educed the conclusion by ignoring every clue that supported it.','The analyst inferred the conclusion from the clues that supported it.','educe 的推断应依据线索，不能靠忽略证据得出。','meaning',[q('educe',1,1,'To educe a conclusion from evidence is to?',['draw or infer it from the evidence','erase the evidence from a page','announce it before examining anything'],'draw or infer it from the evidence','educe 可指从材料中推导出结论。'),q('educe',2,1,'A teacher may educe an answer by?',['asking questions that help a student bring it out','giving no prompt and forbidding a reply','changing the answer after it is spoken'],'asking questions that help a student bring it out','educe 也有引出潜在答案的意思。'),q('educe',3,1,'Which sentence uses educe correctly?',['Researchers educed a pattern from several observations.','The cook educed the soup into a bowl by pouring it.','She educed her shoes because they were wet.'],'Researchers educed a pattern from several observations.','从观察中推断模式是自然用法。'),q('educe',4,1,'The historical sense of educe is closest to?',['bring out or draw forth','bury deeply','break into pieces'],'bring out or draw forth','拉丁来源含“引出、带出”之意。')]);

put('eel','eel 源自古英语 ǣl，属于古老日耳曼语词；现代名词指身体细长、外形像蛇的鱼类。',c('eel.s1','海洋生物','At dusk, a moray eel emerged from a reef crevice, its long body weaving between rocks as small fish scattered.','黄昏时，一条海鳗从礁石缝中钻出，细长的身体在岩石间穿行，小鱼纷纷散开。','At dusk / a moray eel emerged from a reef crevice / its long body weaving between rocks / as small fish scattered.','eel 作 emerged 的主语；现在分词短语补充身体运动状态。','海鳗是 eel 的一种，细长身体和礁石栖息环境符合鱼类义。'),'The eel was a feathered bird that nested in a tree above the water.','The heron was a feathered bird that nested in a tree above the water.','eel 是鱼，不是有羽毛并筑巢的鸟。','meaning',[q('eel',1,1,'An eel is a fish with a body that is usually?',['long and smooth','covered in feathers','shaped like a square shell'],'long and smooth','eel.s1 指身体细长、光滑的鱼。'),q('eel',2,1,'Where might a moray eel hide?',['in a rocky reef crevice','in a bird’s nest','inside a dry paper envelope'],'in a rocky reef crevice','海鳗常躲在礁石缝中。'),q('eel',3,1,'Which phrase is a natural description of an eel?',['a sinuous fish moving through water','a winged mammal gliding through air','a tree rooted in a wetland'],'a sinuous fish moving through water','细长弯曲的水生鱼类符合 eel。'),q('eel',4,1,'A fisherman who catches an eel has caught?',['a fish','a reptile egg','a wooden tool'],'a fish','eel 是鱼类名称。')]);

put('efface','efface 源自法语 effacer“擦去”，经拉丁语 ex-“去掉”与 facies“表面、形貌”形成；可指抹去痕迹，也可指使自己不显眼。',c('efface.s1','修复文物','Conservators used a reversible treatment to soften the ink stain without effacing the original inscription beneath it.','文物修复人员采用可逆处理淡化墨渍，同时没有抹去下面的原始铭文。','Conservators used a reversible treatment / to soften the ink stain / without effacing the original inscription beneath it.','efface 以 inscription 为宾语；without 后接动名词，说明处理时避免的结果。','保护铭文而去除墨渍，对应 efface.s1 的擦除义。'),'The restorer effaced the stain by making the original letters darker and easier to read.','The restorer highlighted the original letters while removing the stain.','让字迹更清楚不叫抹去；efface 是使痕迹淡去或消失。','meaning',[q('efface',1,1,'To efface a mark is to?',['erase or make it fade','copy it onto another page','measure its temperature'],'erase or make it fade','efface.s1 指抹去、使痕迹消失。'),q('efface',2,2,'An artist who effaces herself in a group discussion tries to?',['avoid drawing attention to herself','take control of every conversation','remove paint from a wall'],'avoid drawing attention to herself','efface oneself 表示不使自己显眼。'),q('efface',3,1,'Which action could efface a pencil line?',['rubbing it out carefully','tracing it with a darker pen','framing the paper'],'rubbing it out carefully','擦掉铅笔线体现 efface 的擦除义。'),q('efface',4,1,'Which object can be effaced in the literal sense?',['a chalk mark on a board','a mountain range by a whispered word','a person’s height by changing a label'],'a chalk mark on a board','可擦除的是表面痕迹。')]);

put('effectively','effectively 由 effective 加 -ly 构成；可表示有效地产生预期结果，也可表示实际上、就实际效果而言。',c('effectively.s1','公共卫生','The new reminder system worked effectively: missed appointments fell, and patients received follow-up calls before their prescriptions ran out.','新的提醒系统有效运作：漏诊预约减少，患者也在处方药用完前接到了随访电话。','The new reminder system worked effectively / missed appointments fell / and patients received follow-up calls / before their prescriptions ran out.','effectively 修饰 worked，说明系统达到了预期效果；冒号后列出结果。','预约漏失减少且随访及时，证明系统有效。'),'The alarm worked effectively because it never sounded when smoke filled the room.','The alarm failed to work effectively because it never sounded when smoke filled the room.','烟雾出现时报警器没有响，说明系统未达到预期效果。','meaning',[q('effectively',1,1,'A treatment works effectively when it?',['produces the intended benefit','is expensive regardless of results','is described in a long report'],'produces the intended benefit','effectively.s1 表示有效地达到目的。'),q('effectively',2,2,'If a road closure effectively cuts the village off, the village is?',['for practical purposes isolated','officially declared a new country','physically moved elsewhere'],'for practical purposes isolated','effectively.s2 表示实际上造成某种结果。'),q('effectively',3,1,'Which result suggests a study method works effectively?',['students retain more of the material','students cannot recall anything','the lessons take longer with no improvement'],'students retain more of the material','学习效果改善说明方法有效。'),q('effectively',4,2,'“The service was effectively unavailable” means it was?',['practically unusable even if not formally shut down','always available at every moment','officially renamed'],'practically unusable even if not formally shut down','effectively 可表示实际上、事实上。')]);

put('effectiveness','effectiveness 由 effective 加名词后缀 -ness 构成，表示方法、政策或治疗实现目标的程度。',c('effectiveness.s1','医疗研究','The trial measured the effectiveness of the vaccine by comparing infection rates in the vaccinated group with those in the control group.','试验通过比较接种组与对照组的感染率来衡量疫苗的有效性。','The trial measured the effectiveness of the vaccine / by comparing infection rates / in the vaccinated group / with those in the control group.','effectiveness 是 measured 的宾语；by comparing 说明评估方法。','比较目标结果可检验疫苗是否有效及其有效程度。'),'The study measured the vaccine’s effectiveness by ignoring infection rates and counting the color of the clinic walls.','The study measured the clinic’s decoration by counting the color of its walls.','墙壁颜色与疫苗是否达到预防感染的目标无关。','meaning',[q('effectiveness',1,1,'A study of a policy’s effectiveness asks?',['how well it achieves its intended goal','how many letters its name contains','whether its paper is blue'],'how well it achieves its intended goal','effectiveness.s1 表示实现预期目标的效力。'),q('effectiveness',2,1,'Which evidence could test a medicine’s effectiveness?',['whether symptoms improve under controlled conditions','the shape of its package alone','the number of shelves in the pharmacy'],'whether symptoms improve under controlled conditions','观察症状结果能评估药物效果。'),q('effectiveness',3,1,'Effectiveness is most closely related to?',['success in producing a desired result','the cost of an item by itself','the speed of reading a label'],'success in producing a desired result','有效性关注结果，而不是单独关注价格。'),q('effectiveness',4,1,'A highly effective filter would?',['remove most of the material it is designed to catch','let all particles pass through','change the color of the room'],'remove most of the material it is designed to catch','能捕获目标物质体现过滤器有效。')]);

put('effectual','effectual 来自 effect 加形容词后缀 -ual，表示能成功产生预期结果；较正式，通常强调实际效力。',c('effectual.s1','行政改革','The committee adopted an effectual complaints procedure that acknowledged each report, assigned an investigator, and set a clear deadline.','委员会采用了一套有效的投诉程序：确认每份报告、指派调查员并设定明确期限。','The committee adopted an effectual complaints procedure / that acknowledged each report / assigned an investigator / and set a clear deadline.','effectual 修饰 procedure；that 引导定语从句，说明其有效运作方式。','程序有受理、调查和期限安排，能够处理投诉并达成目的。'),'The proposed rule was effectual because nobody followed it and the problem continued unchanged.','The proposed rule was ineffectual because nobody followed it and the problem continued unchanged.','无人遵守且问题未改善，表明规则没有产生预期效果。','meaning',[q('effectual',1,1,'An effectual remedy is one that?',['successfully solves or reduces the problem','makes the problem impossible to observe','has no practical consequence'],'successfully solves or reduces the problem','effectual.s1 指有效、能产生预期结果。'),q('effectual',2,1,'Which response was effectual in stopping a leak?',['a repair that sealed the pipe and kept it dry','a note describing the leak while water kept flowing','a paint color chosen for the ceiling'],'a repair that sealed the pipe and kept it dry','修复后不再漏水，说明措施奏效。'),q('effectual',3,1,'Effectual is closest in meaning to?',['effective','decorative','uncertain'],'effective','effectual 与 effective 都表示有效。'),q('effectual',4,1,'A plan without any measurable result is unlikely to be?',['effectual','written','discussed'],'effectual','没有实际结果的计划难称 effectual。')]);

put('effectuate','effectuate 源自 effect 加动词后缀 -uate，意为使计划、协议或变化真正生效；语体较正式。',c('effectuate.s1','法律协议','The parties signed the transfer documents to effectuate the sale, after which ownership passed to the buyer.','双方签署过户文件以使交易正式生效，随后所有权转给买方。','The parties signed the transfer documents / to effectuate the sale / after which ownership passed to the buyer.','effectuate 后接 sale 作宾语；to-infinitive 表示签署文件的目的。','文件使买卖协议落实并引发所有权转移，体现 effectuate.s1。'),'The committee effectualized the agreement by leaving it unsigned and refusing to carry it out.','The committee failed to effectuate the agreement because it left it unsigned and unimplemented.','未签署也未执行意味着协议没有被落实；effectuate 强调使其生效。','meaning',[q('effectuate',1,1,'To effectuate a plan is to?',['put it into effect','write it down and abandon it','change its spelling'],'put it into effect','effectuate.s1 指使计划真正实施。'),q('effectuate',2,1,'Which action could effectuate a treaty?',['ratifying it and carrying out its terms','mentioning it without approval','filing it away unread'],'ratifying it and carrying out its terms','批准并执行条款可使条约落实。'),q('effectuate',3,1,'Effectuate is most likely found in?',['formal administrative or legal writing','a casual name for a sandwich','a weather forecast for wind speed'],'formal administrative or legal writing','effectuate 语体较正式。'),q('effectuate',4,1,'A signed order can effectuate a change by?',['making the change operative','preventing it from taking place','describing an unrelated event'],'making the change operative','使改变开始生效就是 effectuate。')]);

put('effervesce','effervesce 源自拉丁语 effervescere“沸腾、冒泡”，与 fervēre“沸腾”相关；现代动词多指液体起泡，也可比喻活泼兴奋。',c('effervesce.s1','饮料化学','When the tablet dissolved in water, the liquid began to effervesce, releasing tiny bubbles that rose continuously to the surface.','药片溶于水时，液体开始起泡，细小气泡不断升到水面。','When the tablet dissolved in water / the liquid began to effervesce / releasing tiny bubbles / that rose continuously to the surface.','effervesce 作 began to 后的动词原形；现在分词短语说明起泡的表现。','溶液释放并上升气泡，体现 effervesce.s1。'),'The soda stopped effervescing, and every bubble vanished before the sealed bottle was opened.','The soda continued to effervesce, and bubbles rose when the bottle was opened.','effervesce 表示产生气泡；气泡消失且不起泡与此相反。','meaning',[q('effervesce',1,1,'A liquid that effervesces?',['releases bubbles of gas','turns instantly into solid stone','loses all color without moving'],'releases bubbles of gas','effervesce.s1 指起泡、冒气泡。'),q('effervesce',2,1,'What would you see when an antacid tablet makes water effervesce?',['bubbles rising through the water','the water freezing into a block','the glass shrinking in size'],'bubbles rising through the water','气泡上升是液体起泡的可见表现。'),q('effervesce',3,1,'Which drink is most likely to effervesce when opened?',['a carbonated soda','still water with no dissolved gas','a dry biscuit'],'a carbonated soda','汽水中的气体释放时会冒泡。'),q('effervesce',4,1,'In a laboratory note, effervesce is closest to?',['fizz','solidify','evaporate silently'],'fizz','effervesce 与 fizz 都可表示冒泡。')]);

put('efficacious','efficacious 源自拉丁语 efficax“有效的”，与 efficere“完成、实现”相关；常用于药物或措施产生预期效果。',c('efficacious.s1','临床药理','The review found the treatment efficacious in reducing fever, although it called for a larger trial to assess uncommon side effects.','评审发现该疗法能有效退烧，不过仍要求开展更大规模试验来评估罕见副作用。','The review found the treatment efficacious in reducing fever / although it called for a larger trial / to assess uncommon side effects.','efficacious 作宾语补足语形容 treatment；although 引出疗效之外的研究限制。','有降低发热的观察结果支持“有效”义，同时未夸大结论。'),'The remedy was efficacious at curing fever because patients’ temperatures never changed.','The remedy was ineffective at curing fever because patients’ temperatures never changed.','体温毫无变化表明疗法未达到退烧目的。','meaning',[q('efficacious',1,1,'An efficacious medicine is one that?',['produces the intended medical effect','has a pleasant label only','is impossible to administer'],'produces the intended medical effect','efficacious.s1 指药物有效、能达到预期效果。'),q('efficacious',2,1,'Which evidence supports calling a treatment efficacious?',['patients improve more often than under a suitable control','the bottle is an attractive color','the medicine has a long name'],'patients improve more often than under a suitable control','与合理对照相比改善更多，才支持疗效判断。'),q('efficacious',3,1,'Efficacious is closest in meaning to?',['effective','ornamental','temporary'],'effective','efficacious 与 effective 都表示有效。'),q('efficacious',4,1,'A researcher should avoid calling a drug efficacious when?',['reliable trials show no intended benefit','a study measures relevant outcomes','patients receive monitored care'],'reliable trials show no intended benefit','没有目标疗效的可靠证据时不能称其有效。')]);

put('efficacy','efficacy 源自拉丁语 efficacia“效力、有效性”，与 efficax“有效的”同源，常指药物或措施产生预期效果的能力。',c('efficacy.s1','药物评价','The regulator reviewed the drug’s efficacy using prespecified outcomes, including how often patients recovered without additional treatment.','监管机构根据预先规定的指标评估该药的功效，其中包括患者无需追加治疗而康复的比例。','The regulator reviewed the drug’s efficacy / using prespecified outcomes / including how often patients recovered / without additional treatment.','efficacy 是 reviewed 的宾语；using 短语说明评价依据。','预先设定的临床结果用于判断药物能否有效治疗。'),'The team established the drug’s efficacy by measuring the color of its packaging instead of any patient outcome.','The team assessed the drug’s packaging by measuring its color instead of any patient outcome.','包装颜色不反映药物是否达到治疗效果。','meaning',[q('efficacy',1,1,'A drug’s efficacy concerns its?',['ability to produce a desired medical effect','market price by itself','packaging material'],'ability to produce a desired medical effect','efficacy.s1 指药物功效、疗效。'),q('efficacy',2,1,'Which measurement is relevant to a treatment’s efficacy?',['whether the target symptoms improve','the font on its box','the number of windows in the clinic'],'whether the target symptoms improve','目标症状是否改善能衡量疗效。'),q('efficacy',3,1,'Efficacy is most closely related to?',['effectiveness','appearance','weight'],'effectiveness','efficacy 表示有效性或功效。'),q('efficacy',4,1,'A trial with no improvement in the target condition provides?',['little evidence of efficacy','proof of perfect efficacy','a measure of the medicine’s color'],'little evidence of efficacy','缺少目标改善就缺少有效性证据。')]);

put('efficiently','efficiently 由 efficient 加副词后缀 -ly 构成，表示以较少时间、精力或资源实现目标；不单纯等于做得快。',c('efficiently.s1','能源管理','The building’s heating system now runs efficiently, keeping rooms comfortable while using less electricity than the old equipment.','大楼的供暖系统现在运行高效，在让房间保持舒适的同时，比旧设备耗电更少。','The building’s heating system now runs efficiently / keeping rooms comfortable / while using less electricity than the old equipment.','efficiently 修饰 runs；while 对比舒适效果与较低资源消耗。','以较少电力达到相同舒适目标，体现效率。'),'The pump worked efficiently by consuming twice as much power to move half as much water.','The pump worked inefficiently by consuming twice as much power to move half as much water.','用更多能量搬运更少水量，说明资源利用低效。','meaning',[q('efficiently',1,1,'A machine operates efficiently when it?',['achieves its task with little wasted energy','uses maximum fuel for minimum output','runs quickly but never completes its task'],'achieves its task with little wasted energy','efficiently.s1 强调少浪费地达到目标。'),q('efficiently',2,1,'Which office change could help staff work efficiently?',['organizing files so needed records are found quickly','duplicating every task without coordination','hiding the instructions'],'organizing files so needed records are found quickly','减少查找和重复劳动可提高效率。'),q('efficiently',3,1,'A route planned efficiently would usually?',['save time or fuel while reaching the destination','add detours without any benefit','stop before arriving'],'save time or fuel while reaching the destination','高效路线以较少资源到达目的地。'),q('efficiently',4,1,'Efficiently differs from merely quickly because it also considers?',['the resources and effort used','the color of the equipment','the age of the operator'],'the resources and effort used','效率还要看时间、精力或资源是否浪费。')]);

put('effigy','effigy 源自拉丁语 effigies“肖像、形象”，经法语进入英语；指代表某个人的雕像或模拟人像，常用于示威中焚烧。',c('effigy.s1','历史抗议','Protesters burned an effigy of the governor outside the courthouse, using the symbolic act to express anger at his decision.','抗议者在法院外焚烧州长的模拟人像，以这种象征性行为表达对其决定的不满。','Protesters burned an effigy of the governor / outside the courthouse / using the symbolic act / to express anger at his decision.','effigy 作 burned 的宾语；of 短语说明人像代表谁。','替代州长形象的人像是 effigy，焚烧行为具有象征意义。'),'The crowd burned an effigy that was an actual photograph of a landscape with nobody represented.','The crowd burned a landscape print that represented no person.','effigy 必须代表某个人；无人像特征的风景图不是 effigy。','meaning',[q('effigy',1,1,'An effigy is an image or figure that?',['represents a particular person','measures the depth of a river','records the sound of a bell'],'represents a particular person','effigy.s1 是代表某人的人像或塑像。'),q('effigy',2,1,'Why might protesters burn an effigy?',['to make a symbolic public protest','to cook food for a picnic','to test a new building material'],'to make a symbolic public protest','焚烧模拟人像常是象征性抗议。'),q('effigy',3,1,'Which object could be called an effigy of a ruler?',['a straw figure dressed to resemble the ruler','an unmarked stone from a river','a map showing the ruler’s country'],'a straw figure dressed to resemble the ruler','装扮成统治者的草人代表该人物。'),q('effigy',4,1,'Effigy is closest in meaning to?',['likeness or represented figure','weather forecast','legal contract'],'likeness or represented figure','effigy 指人物形象或替身像。')]);

put('effluent','effluent 来自拉丁语 effluere“流出”，由 ex-“向外”与 fluere“流动”构成；作名词指排出的废液，也可作形容词表示流出的。',c('effluent.s1','水质监管','The factory must treat its effluent before discharge, and inspectors sample the outlet to check for harmful chemicals.','工厂必须处理排放废水后才能排出，检查人员会采集出水口样本检测有害化学物质。','The factory must treat its effluent before discharge / and inspectors sample the outlet / to check for harmful chemicals.','effluent 作 treat 的宾语，指工厂排放液体；before discharge 表示排放前处理。','工厂废液需经处理和检测，符合 effluent.s1。'),'The plant released clean drinking water as toxic effluent into the river without any contaminants.','The plant released untreated effluent into the river, where it could contaminate the water.','effluent 在这里是排出的废液；无污染的饮用水不符合该语境。','meaning',[q('effluent',1,1,'Industrial effluent is usually?',['liquid waste flowing out of a facility','a solid wall around a factory','fresh air drawn into a building'],'liquid waste flowing out of a facility','effluent.s1 指排出的废液或废水。'),q('effluent',2,2,'An effluent stream from a spring is?',['flowing outward from its source','moving inward toward a sealed tank','completely motionless'],'flowing outward from its source','effluent.s2 作形容词表示流出的。'),q('effluent',3,1,'Why test factory effluent before it enters a river?',['to detect harmful substances in the discharge','to determine the river’s color for decoration','to make the waste heavier'],'to detect harmful substances in the discharge','检测排放物可发现污染物。'),q('effluent',4,1,'Which sentence uses effluent as a noun?',['The plant filtered its effluent before release.','The effluent pipe was painted green.','An effluent current moved away from the outlet.'],'The plant filtered its effluent before release.','此句中 effluent 作 filtered 的宾语，是名词。')]);

put('effortlessly','effortlessly 由 effortless 加副词后缀 -ly 构成，意为看起来毫不费力地；常描述熟练动作，不表示任务本身没有难度。',c('effortlessly.s1','音乐演奏','After years of practice, the pianist moved effortlessly through the difficult passage while keeping the melody clear.','经过多年练习，钢琴家流畅地弹过那段困难乐句，同时保持旋律清晰，动作看起来毫不费力。','After years of practice / the pianist moved effortlessly through the difficult passage / while keeping the melody clear.','effortlessly 修饰 moved；while keeping 表示演奏同时保持的效果。','多年练习使难段演奏显得轻松，体现“看似不费力”。'),'The pianist struggled to move effortlessly through the passage, stopping after every note because it was easy.','The pianist struggled through the passage, stopping after every note because it was difficult.','每音停顿和挣扎不符合 effortlessly 所表达的轻松流畅。','meaning',[q('effortlessly',1,1,'Someone who moves effortlessly appears to move?',['with little visible strain','only after great hesitation','without moving at all'],'with little visible strain','effortlessly.s1 表示看起来毫不费力。'),q('effortlessly',2,1,'A trained dancer may leap effortlessly because?',['practice has made the movement look easy','the dancer has never learned the step','the floor is made of paper'],'practice has made the movement look easy','熟练练习可以让高难动作看起来轻松。'),q('effortlessly',3,1,'Which performance sounds effortless?',['a speaker gives a fluent talk without visible strain','a speaker pauses after each word and loses the thread','a speaker refuses to begin'],'a speaker gives a fluent talk without visible strain','流畅自然、少有明显吃力符合 effortless。'),q('effortlessly',4,1,'Does effortlessly prove that a task required no practice?',['No; a practiced skill can only look easy','Yes; it always means no effort was ever needed','Yes; it means the person is asleep'],'No; a practiced skill can only look easy','effortlessly 常指表现看似轻松，背后仍可能有练习。')]);

put('effrontery','effrontery 源自法语 effronterie，最终与拉丁语 frons“额头、脸面”相关；指厚颜无耻、毫无羞耻感的冒犯大胆。',c('effrontery.s1','职场礼仪','The consultant had the effrontery to present a colleague’s research as his own, even though the team had documented who did the work.','顾问竟厚颜无耻地把同事的研究说成自己的，尽管团队已记录了工作分工。','The consultant had the effrontery / to present a colleague’s research as his own / even though the team had documented who did the work.','effrontery 作 had 的宾语；不定式解释厚颜无耻行为的具体内容。','明知有记录仍冒领成果，是公然无耻而非普通勇敢。'),'She showed effrontery by quietly accepting responsibility and apologizing for the mistake.','She showed humility by quietly accepting responsibility and apologizing for the mistake.','主动承担责任并道歉表现谦逊，和 effrontery 的厚颜相反。','meaning',[q('effrontery',1,1,'Effrontery is best described as?',['rude, shameless boldness','quiet gratitude','careful measurement'],'rude, shameless boldness','effrontery.s1 指厚颜无耻的冒犯行为。'),q('effrontery',2,1,'Which act shows effrontery?',['claiming another person’s work despite knowing the truth','crediting the colleague who did the research','asking permission before using an idea'],'claiming another person’s work despite knowing the truth','明知不实仍冒领成果体现厚颜。'),q('effrontery',3,1,'Effrontery usually carries what tone?',['strong disapproval of shameless behavior','warm praise for modesty','neutral interest in weather'],'strong disapproval of shameless behavior','这个词通常带明显贬义。'),q('effrontery',4,1,'A person who behaves with effrontery is unlikely to feel?',['ashamed of the offense','entitled to demand more','bold enough to intrude'],'ashamed of the offense','effrontery 指毫无羞耻感的大胆。')]);

put('effuse','effuse 源自拉丁语 effundere“倾泻、流出”，由 ex-“向外”与 fundere“倾倒”构成；指液体、气体或情感自由涌出。',c('effuse.s1','艺术评论','Warm light effused from the open studio into the dark courtyard, making the wet paving stones glow.','温暖的灯光从敞开的工作室涌入黑暗庭院，使湿润的铺路石泛起光亮。','Warm light effused from the open studio / into the dark courtyard / making the wet paving stones glow.','effuse 作不及物动词描述光向外流散；into 短语标明扩散方向。','灯光由室内向庭院散出，符合流出义。'),'The fragrance effused into the room by remaining sealed inside an airtight bottle.','The fragrance stayed sealed inside the airtight bottle instead of effusing into the room.','气味若封在密闭瓶中就没有向外扩散。','meaning',[q('effuse',1,1,'When light effuses from a doorway, it?',['flows or spreads outward','is locked permanently inside a box','turns into a solid wall'],'flows or spreads outward','effuse.s1 表示向外流出、散发。'),q('effuse',2,1,'Which substance can effuse through an opening?',['a scent spreading from a flower shop','a brick that cannot move','a written rule kept in a folder'],'a scent spreading from a flower shop','气味可以从店内向外散发。'),q('effuse',3,1,'The verb effuse is historically linked to which action?',['pouring or flowing out','folding paper inward','counting objects twice'],'pouring or flowing out','拉丁词源含“倾倒、流出”之意。'),q('effuse',4,1,'Which phrase uses effuse naturally?',['sunlight effused across the floor','the chair effused a number into a list','she effused the door by locking it'],'sunlight effused across the floor','光线铺散到地板上是自然搭配。')]);

put('egalitarian','egalitarian 由 égal“平等的”及 -arian 构成，经法语与拉丁语 aequalis“相等的”相关；指主张或体现人人平等权利的。',c('egalitarian.s1','社会政策','The egalitarian proposal gives workers at every grade the same right to appeal a decision, rather than reserving that right for managers.','这项平等主义提案赋予各级员工同等的申诉权，而不是只把该权利留给管理人员。','The egalitarian proposal gives workers at every grade the same right to appeal a decision / rather than reserving that right for managers.','egalitarian 修饰 proposal；rather than 对比平等原则与等级特权。','同等申诉权体现平等权利，而非按等级区别对待。'),'The policy was egalitarian because only senior managers could vote and junior staff had no rights.','The policy was hierarchical because only senior managers could vote and junior staff had no rights.','只给高层投票权体现等级制度，并非平等主义。','meaning',[q('egalitarian',1,1,'An egalitarian system aims to provide?',['equal rights or status','permanent privileges for one small group','different laws for every person'],'equal rights or status','egalitarian.s1 以人人平等为原则。'),q('egalitarian',2,1,'Which workplace rule is most egalitarian?',['all staff may use the same appeal process','only executives may report safety concerns','new employees receive no protection'],'all staff may use the same appeal process','平等适用申诉权体现 egalitarian。'),q('egalitarian',3,1,'Egalitarian is most closely associated with?',['equality','hereditary rank','exclusive privilege'],'equality','词根与 equal 有关，强调平等。'),q('egalitarian',4,1,'A critic might call a society non-egalitarian if it?',['denies equal rights to a class of people','applies the same rule to everyone','shares public services fairly'],'denies equal rights to a class of people','剥夺群体平等权利与平等主义相悖。')]);

put('eggshell','eggshell 是 egg 与 shell 构成的复合词，字面指鸟蛋外层脆壳；也可作形容词指浅淡的蛋壳色或极易受伤的状态。',c('eggshell.s1','自然观察','A thin eggshell cracked under the chick’s beak, and a narrow opening appeared as the bird pushed from inside.','薄薄的蛋壳在雏鸟的喙下裂开；随着雏鸟从里面顶出，一个窄缝出现了。','A thin eggshell cracked under the chick’s beak / and a narrow opening appeared / as the bird pushed from inside.','eggshell 作 cracked 的主语；as 从句说明裂缝出现时雏鸟的动作。','雏鸟从蛋内顶破外壳，体现 eggshell 的字面义。'),'The eggshell protected the chick as a soft inner liquid with no hard outer layer.','The albumen surrounded the chick as a soft inner liquid beneath the hard eggshell.','蛋壳是外层硬壳；蛋白是内部液体。','meaning',[q('eggshell',1,1,'An eggshell is the?',['outer covering of a bird’s egg','liquid inside an egg','nest built from twigs'],'outer covering of a bird’s egg','eggshell.s1 指蛋的外壳。'),q('eggshell',2,1,'Why is an eggshell described as fragile?',['it can crack under pressure','it is made of flexible rubber','it grows into a feather'],'it can crack under pressure','蛋壳较脆，容易受压破裂。'),q('eggshell',3,1,'Eggshell white usually names?',['a pale, slightly warm color','a bright black pigment','a type of green metal'],'a pale, slightly warm color','eggshell 也可指类似蛋壳的浅色。'),q('eggshell',4,1,'A person walking on eggshells is acting?',['very cautiously to avoid upsetting someone','carelessly and loudly','as if walking on a beach'],'very cautiously to avoid upsetting someone','walk on eggshells 是小心谨慎的习语。')]);

put('egocentric','egocentric 由 ego“自我”、centr“中心”与 -ic 构成，指总把自己当作关注中心、难以顾及他人观点的。',c('egocentric.s1','团队协作','The egocentric team leader praised only his own ideas and interrupted colleagues whenever they described a different approach.','这位自我中心的团队负责人只夸自己的想法，同事一提出不同方法就被他打断。','The egocentric team leader praised only his own ideas / and interrupted colleagues / whenever they described a different approach.','egocentric 修饰 leader；whenever 从句描述他反复出现的行为。','只关注自己并压制他人意见，符合 egocentric 的含义。'),'The egocentric volunteer listened carefully to every neighbor and put their needs ahead of his own.','The considerate volunteer listened carefully to every neighbor and put their needs ahead of his own.','认真倾听并优先考虑他人体现体贴，和 egocentric 自我中心相反。','meaning',[q('egocentric',1,1,'An egocentric person tends to?',['focus mainly on themselves','consider every viewpoint equally','avoid talking about personal interests'],'focus mainly on themselves','egocentric.s1 指以自我为中心。'),q('egocentric',2,1,'Which behavior is egocentric in a meeting?',['one person keeps redirecting every topic to personal achievements','members take turns sharing concerns','the chair invites quiet members to speak'],'one person keeps redirecting every topic to personal achievements','把话题反复拉回自己身上体现自我中心。'),q('egocentric',3,1,'The element centr in egocentric suggests?',['a center','a written promise','a change of color'],'a center','centr 表示中心；ego 是自我。'),q('egocentric',4,1,'Which adjective is an opposite of egocentric?',['considerate','self-absorbed','self-focused'],'considerate','considerate 体谅他人，与只顾自己的 egocentric 相反。')]);

put('egocentrism','egocentrism 由 egocentric 加名词后缀 -ism 构成；指以自我为中心的倾向，也可指儿童尚难采取他人视角的认知特点。',c('egocentrism.s1','儿童发展','The researcher distinguished a child’s egocentrism from selfishness: the child simply could not yet imagine what another observer could see.','研究者把儿童的自我中心与自私区分开来：孩子当时只是还不能想象另一位观察者看到了什么。','The researcher distinguished a child’s egocentrism from selfishness / the child simply could not yet imagine / what another observer could see.','egocentrism 作 distinguished 的宾语；冒号解释发展心理学中的视角限制。','不能理解他人视角是该词在儿童认知中的特定含义。'),'The experiment called it egocentrism when the child accurately described the scene from every observer’s viewpoint.','The experiment found perspective-taking when the child accurately described the scene from every observer’s viewpoint.','能够准确采用每位观察者视角，恰好不是视角受限的 egocentrism。','meaning',[q('egocentrism',1,1,'In child development, egocentrism can mean difficulty?',['imagining another person’s point of view','recognizing one’s own name','learning the color of an object'],'imagining another person’s point of view','egocentrism.s1 可指儿童难以换位思考。'),q('egocentrism',2,1,'Egocentrism is not always the same as selfishness because it may reflect?',['a cognitive limit in perspective-taking','a deliberate plan to harm others','a lack of physical strength'],'a cognitive limit in perspective-taking','儿童可能是认知上难以采取他人视角，而非故意自私。'),q('egocentrism',3,1,'Which task might reveal egocentrism in a young child?',['asking what a doll can see from its position','asking the child to name a familiar toy','asking the child to count three blocks'],'asking what a doll can see from its position','视角任务可测试儿童是否理解他人所见。'),q('egocentrism',4,1,'The suffix -ism in egocentrism helps form a noun for?',['a tendency or condition','a person who edits books','a tool for measuring heat'],'a tendency or condition','-ism 常形成表示倾向或状态的名词。')]);

put('egoism','egoism 由 ego“自我”加 -ism 构成；在伦理学中指把自我利益作为行动原则，也常泛指自私利己。',c('egoism.s1','伦理学讨论','The philosopher compared ethical egoism, which treats self-interest as a guiding principle, with theories that emphasize duties to others.','这位哲学家把伦理利己主义——将自身利益视为行动原则——与强调对他人义务的理论作了比较。','The philosopher compared ethical egoism / which treats self-interest as a guiding principle / with theories / that emphasize duties to others.','egoism 是 compared 的宾语；which 从句解释该伦理学立场。','将自身利益作为道德行动原则，符合 egoism.s1 的哲学义。'),'The essay defined egoism as the rule that everyone must always sacrifice personal interests for strangers.','The essay defined altruism as the rule that people should sacrifice personal interests to help others.','为他人牺牲自身利益更接近利他主义，不是利己主义。','meaning',[q('egoism',1,1,'Ethical egoism treats which consideration as central?',['the agent’s own interest','the color of a written rule','the age of a building'],'the agent’s own interest','egoism.s1 指以自身利益为行动原则。'),q('egoism',2,1,'Which action might be described as egoistic in ordinary use?',['taking the shared credit while giving none to teammates','volunteering time without seeking reward','sharing resources fairly'],'taking the shared credit while giving none to teammates','只为自己争取好处符合日常贬义的 egoism。'),q('egoism',3,1,'Egoism is often contrasted with?',['altruism','geology','arithmetic'],'altruism','altruism 强调关心和帮助他人，与利己相对。'),q('egoism',4,1,'The root ego refers to?',['the self','a river','a book cover'],'the self','ego 表示“自我”，构成 egoism。')]);

put('egoist','egoist 由 ego“自我”与表示人的后缀 -ist 构成；可指主张自利原则的人，也可泛指自私的人。',c('egoist.s1','哲学课堂','As an egoist, the character argues that each person should pursue personal interests, though the class questions what happens to shared obligations.','作为利己主义者，这个角色主张人人都应追求个人利益，不过全班也追问共同义务该如何处理。','As an egoist / the character argues / that each person should pursue personal interests / though the class questions what happens to shared obligations.','egoist 作 as 的宾语；that 从句概述其主张，though 引出讨论。','主张个人利益优先的人符合 egoist 的哲学义。'),'The egoist devoted every decision to helping strangers and never considered personal benefit.','The altruist devoted every decision to helping strangers and never considered personal benefit.','完全以帮助他人为重且不顾自身利益更符合 altruist。','meaning',[q('egoist',1,1,'An egoist is a person who?',['places personal interests at the center','works only as a geologist','never makes any decision'],'places personal interests at the center','egoist.s1 指利己主义者或自私者。'),q('egoist',2,1,'In a philosophy debate, an egoist might defend?',['pursuing one’s own interests as a principle','giving away every possession by definition','never choosing between alternatives'],'pursuing one’s own interests as a principle','这是 egoist 的伦理学立场。'),q('egoist',3,1,'Which word is a likely opposite of egoist?',['altruist','self-seeker','egotist'],'altruist','altruist 重视他人，与利己者相对。'),q('egoist',4,1,'The suffix -ist in egoist identifies?',['a person associated with a belief or practice','a past event','a container for liquid'],'a person associated with a belief or practice','-ist 常表示持某种立场或从事某种活动的人。')]);

put('egoistic','egoistic 由 ego“自我”加形容词后缀 -istic 构成，表示只顾自身利益的；在伦理学讨论中也可描述利己主义立场。',c('egoistic.s1','资源分配','The reviewer called the proposal egoistic because it protected the sponsor’s profits while shifting every environmental cost onto nearby residents.','评论者称该提案自私，因为它保护资助方利润，却把所有环境成本转嫁给附近居民。','The reviewer called the proposal egoistic / because it protected the sponsor’s profits / while shifting every environmental cost onto nearby residents.','egoistic 作宾语补足语，说明 proposal 的性质；because 引出判断依据。','只保自身利益并把负担推给别人体现 egoistic。'),'The egoistic agreement divided every benefit and every burden equally among all participants.','The fair agreement divided every benefit and every burden equally among all participants.','利益和负担均等分配体现公平，并非只顾自身的 egoistic。','meaning',[q('egoistic',1,1,'An egoistic decision mainly serves?',['the decision-maker’s own interests','every participant equally','no one’s interests at all'],'the decision-maker’s own interests','egoistic.s1 表示只顾自身利益。'),q('egoistic',2,1,'Which policy is egoistic?',['one that keeps all gains for its author and transfers costs to others','one that shares benefits and burdens fairly','one that is revised after public consultation'],'one that keeps all gains for its author and transfers costs to others','只让自己获益、让别人承担代价，体现自私。'),q('egoistic',3,1,'Egoistic is closest in meaning to?',['self-centered','generous','impartial'],'self-centered','egoistic 与 self-centered 意义接近。'),q('egoistic',4,1,'Which sentence uses egoistic naturally?',['His egoistic choice ignored the needs of the rest of the team.','The egoistic dissolved into water without residue.','She egoistically blue the report.'],'His egoistic choice ignored the needs of the rest of the team.','该词作形容词修饰 choice，描述自我中心。')]);

put('egotism','egotism 由 ego“自我”加 -tism 构成，指过度谈论自己、夸耀自己或坚信自己优越的自负。',c('egotism.s1','社交场合','At dinner, his egotism was evident: every story returned to his achievements, and he barely asked the other guests a question.','晚餐时他的自负显而易见：每个故事最后都绕回他的成就，他几乎没问其他客人任何问题。','At dinner / his egotism was evident / every story returned to his achievements / and he barely asked the other guests a question.','egotism 作主语补足语名词；冒号后举例说明自我中心的谈话方式。','反复夸耀自身成就并不关心他人，体现 egotism。'),'Her egotism showed when she quietly thanked the whole team and credited their work.','Her humility showed when she quietly thanked the whole team and credited their work.','感谢团队并认可他人贡献体现谦逊，不是自负。','meaning',[q('egotism',1,1,'Egotism involves?',['excessive self-importance and talk about oneself','careful attention to another person’s needs','fear of speaking in public'],'excessive self-importance and talk about oneself','egotism.s1 指自负和过度自我关注。'),q('egotism',2,1,'Which behavior suggests egotism at a meeting?',['claiming every success and dismissing everyone else’s contribution','asking each colleague for input','sharing credit fairly'],'claiming every success and dismissing everyone else’s contribution','独占功劳、贬低他人体现自负。'),q('egotism',3,1,'Egotism differs from quiet confidence because egotism often?',['requires exaggerated attention to oneself','never involves the self','means uncertainty about every fact'],'requires exaggerated attention to oneself','egotism 带有过度自我关注。'),q('egotism',4,1,'A modest person is less likely to display?',['egotism','gratitude','patience'],'egotism','谦逊与自负相反。')]);

put('egress','egress 源自拉丁语 egressus“出去”，来自 ex-“向外”与 gradi“行走”；可作名词指出口或离去，也可作动词表示外出。',c('egress.s1','建筑安全','The fire inspector checked that each basement room had a clear route of egress and that no boxes blocked the emergency door.','消防检查员确认每间地下室都有畅通的出口路线，并检查应急门没有被箱子堵住。','The fire inspector checked / that each basement room had a clear route of egress / and that no boxes blocked the emergency door.','egress 作介词 of 的宾语；route of egress 是“离开建筑的通道”。','检查安全出口及其畅通状态，体现 egress.s1 名词义。'),'The inspector blocked the only egress so everyone would have an easier way to leave.','The inspector cleared the only egress so everyone would have a safe way to leave.','堵住唯一出口会阻碍离开，与出口供人外出这一功能相反。','meaning',[q('egress',1,1,'A building’s egress is a route for?',['leaving the building','entering a swimming pool only','measuring its height'],'leaving the building','egress.s1 指出口或离去路线。'),q('egress',2,2,'If a visitor egresses from a hall, the visitor?',['goes out of it','builds it from stone','locks everyone inside'],'goes out of it','egress 作动词表示向外离开。'),q('egress',3,1,'Why must an emergency egress remain unobstructed?',['people need to leave quickly and safely','it is used to store furniture','it prevents all movement outdoors'],'people need to leave quickly and safely','畅通出口保障紧急疏散。'),q('egress',4,1,'Egress is opposite in direction to?',['ingress','exit','departure'],'ingress','ingress 表示进入，与 egress 的向外相对。')]);

put('Egyptian','Egyptian 源自 Egypt 加形容词/居民后缀 -ian，经希腊语 Aigyptios 与拉丁语 Aegyptius 传入英语；可指埃及人或埃及的。',c('Egyptian.s2','文化遗产','The museum displayed Egyptian pottery beside a map of the Nile valley, explaining how regional materials shaped the vessels.','博物馆把埃及陶器陈列在尼罗河谷地图旁，并解释当地材料如何影响器皿制作。','The museum displayed Egyptian pottery / beside a map of the Nile valley / explaining how regional materials shaped the vessels.','Egyptian 作定语修饰 pottery，表示与埃及有关；现在分词说明展览内容。','陶器与尼罗河谷文化相关，体现 Egyptian.s2 形容词义。'),'The label called the pottery Egyptian even though it had no connection to Egypt or its people.','The label called the pottery local because it had no connection to Egypt or its people.','没有与埃及或其人民的联系时，称其 Egyptian 缺乏依据。','meaning',[q('Egyptian',1,1,'An Egyptian in the noun sense is?',['a person from Egypt','a person from Peru','a type of river boat'],'a person from Egypt','Egyptian.s1 指埃及人。'),q('Egyptian',2,2,'Egyptian architecture means architecture?',['connected with Egypt or its traditions','built only beneath the ocean','made exclusively from paper'],'connected with Egypt or its traditions','Egyptian.s2 作形容词表示埃及的、与埃及有关的。'),q('Egyptian',3,1,'Which person can accurately be called Egyptian?',['someone from Egypt','someone who has never visited or lived in Egypt by definition','a person born in Egypt’s neighboring sea'],'someone from Egypt','该词可指来自埃及的人。'),q('Egyptian',4,2,'An Egyptian artifact should have a link to?',['Egyptian history, place, or culture','a random modern object with no such connection','a different country solely because of its color'],'Egyptian history, place, or culture','形容词用法要求与埃及有关联。')]);

put('einkorn','einkorn 是德语借词，字面含“一粒谷物”之意；指一种古老栽培小麦 Triticum monococcum，其小穗通常只有一粒谷物。',c('einkorn.s1','古代农业','Archaeologists found charred einkorn grains beside a hearth, evidence that early farmers had stored and prepared this ancient wheat.','考古学家在炉边发现烧焦的单粒小麦，说明早期农民曾储存并加工这种古老小麦。','Archaeologists found charred einkorn grains beside a hearth / evidence that early farmers had stored and prepared this ancient wheat.','einkorn 作 grains 的定语名词；同位语 evidence 解释发现的意义。','该谷物是古老栽培小麦，符合 einkorn.s1。'),'The laboratory identified einkorn as a modern seedless rice that grows only underwater.','The laboratory identified einkorn as an ancient wheat with a single grain in each spikelet.','einkorn 是古老小麦，不是水生无籽稻米。','meaning',[q('einkorn',1,1,'Einkorn is a kind of?',['ancient cultivated wheat','seedless tropical rice','flowering seaweed'],'ancient cultivated wheat','einkorn.s1 指一种古老小麦。'),q('einkorn',2,1,'What distinguishes einkorn’s spikelet in its name’s traditional explanation?',['it bears a single grain','it contains no seed','it grows only below water'],'it bears a single grain','词名来自德语“一粒谷物”的意思。'),q('einkorn',3,1,'Where might archaeologists find evidence of einkorn use?',['charred grains near an ancient hearth','a plastic bottle in a modern shop','a fossilized fish in deep ocean rock'],'charred grains near an ancient hearth','古代谷物遗存可见于炊煮遗址。'),q('einkorn',4,1,'Einkorn is historically important as?',['an early domesticated wheat','a recently invented metal alloy','a type of bird feather'],'an early domesticated wheat','它是古老栽培小麦之一。')]);

put('ejection','ejection 由 eject 加名词后缀 -ion 构成；eject 源自拉丁语 eicere“抛出”，可指物质喷出，也可指人员被强行移除。',c('ejection.s1','火山学','The volcanic ejection sent ash and fragments high into the air, prompting nearby villages to close schools and cover water tanks.','火山喷发物把火山灰和碎屑抛向高空，附近村庄因此关闭学校并遮盖水箱。','The volcanic ejection sent ash and fragments high into the air / prompting nearby villages / to close schools and cover water tanks.','ejection 作主语；prompting 分词短语说明喷出物引发的后果。','火山将物质抛出，体现 ejection 的“喷出”义。'),'The ejection of ash meant the volcano pulled every particle back underground and released nothing.','The retention of ash meant the volcano kept the particles underground and released nothing.','没有物质被抛出不属于 ejection。','meaning',[q('ejection',1,1,'Volcanic ejection refers to?',['material being thrown out of a volcano','rainwater soaking into soil','rock slowly turning into ice'],'material being thrown out of a volcano','ejection.s1 可指火山物质喷出。'),q('ejection',2,1,'A passenger’s ejection from a venue means the passenger was?',['forced to leave','invited to stay longer','asked to repair the building'],'forced to leave','ejection 也可指强行驱逐。'),q('ejection',3,1,'An ejection seat is designed to?',['force an aircraft occupant out in an emergency','keep a pilot permanently inside a plane','measure an aircraft’s fuel'],'force an aircraft occupant out in an emergency','弹射座椅会把乘员弹出飞机。'),q('ejection',4,1,'Which event is an ejection of matter?',['a geyser sending water into the air','a lake quietly freezing','a stone resting on the ground'],'a geyser sending water into the air','把物质抛向外部是 ejection。')]);

put('eke','eke 源自古英语 ēacian“增加、增添”，现代英语常见于 eke out，表示勉强维持收入或把有限供应延长使用。',c('eke.s1','家庭预算','During the dry season, the family eked out its stored grain by mixing it with beans and keeping careful records of each meal.','旱季里，一家人把储粮掺入豆子并仔细记录每餐，尽量让有限的粮食维持更久。','During the dry season / the family eked out its stored grain / by mixing it with beans / and keeping careful records of each meal.','eke out 后接粮食作宾语，表示设法延长有限供应；by 引出做法。','通过节省和混合食材延长储粮使用时间，符合 eke.s1。'),'They eked out their savings by spending the entire amount on one unnecessary purchase.','They exhausted their savings by spending the entire amount on one unnecessary purchase.','一次花光积蓄是耗尽，不是设法让有限资源维持更久。','meaning',[q('eke',1,1,'To eke out a living is to?',['manage to survive on limited income','become wealthy without working','stop earning money permanently'],'manage to survive on limited income','eke out 常指勉强维持生计。'),q('eke',2,1,'A camp tries to eke out its water by?',['rationing what remains','pouring it all away','ordering a flood'],'rationing what remains','节约使用能让有限水源撑得更久。'),q('eke',3,1,'Which sentence uses eke correctly?',['She eked out the last fuel until help arrived.','She eked the fuel by setting it on fire.','She eked out of the room to greet him.'],'She eked out the last fuel until help arrived.','eke out + 资源，表示设法延长其使用。'),q('eke',4,1,'The phrase eke out usually suggests the available amount is?',['limited and being stretched carefully','unlimited and abundant','irrelevant to the action'],'limited and being stretched carefully','eke out 带有资源有限、努力支撑的意味。')]);

put('elaborately','elaborately 由 elaborate 加副词后缀 -ly 构成；elaborate 与拉丁语 elaborare“费力完成”有关，可表示装饰繁复地或详尽地。',c('elaborately.s1','工艺设计','The cabinet was elaborately carved with vines and small birds, yet the maker left the handles plain so the wood grain remained visible.','柜子雕刻繁复，饰有藤蔓和小鸟；不过制作者把把手留得朴素，让木纹依然清晰可见。','The cabinet was elaborately carved with vines and small birds / yet the maker left the handles plain / so the wood grain remained visible.','elaborately 修饰 carved，说明雕刻细节丰富；yet 表示与朴素把手的对照。','复杂细致的装饰体现 elaborately.s1。'),'The plain cabinet was elaborately carved with no decoration, pattern, or visible detail.','The plain cabinet was simply carved with no decoration, pattern, or visible detail.','毫无装饰和细节不能称为繁复雕刻。','meaning',[q('elaborately',1,1,'An elaborately decorated room contains?',['many detailed ornaments or patterns','no decoration at all','only one bare wall'],'many detailed ornaments or patterns','elaborately.s1 表示精细、繁复地装饰。'),q('elaborately',2,1,'An explanation given elaborately is?',['developed with considerable detail','reduced to one unexplained word','delivered without any information'],'developed with considerable detail','elaborately 也表示详尽地。'),q('elaborately',3,1,'Which object is elaborately made?',['a box with intricate hand-cut designs','a blank board with no markings','a rough stone left untouched'],'a box with intricate hand-cut designs','细密手工图案体现制作繁复。'),q('elaborately',4,1,'Elaborately is an adverb that can modify?',['carved','carvinglyness','a because'],'carved','副词 elaborately 可修饰动词 carved。')]);

put('elaborateness','elaborateness 由 elaborate 加名词后缀 -ness 构成，表示细节丰富、装饰繁复或处理精细的程度。',c('elaborateness.s1','建筑装饰','The conservator documented the elaborateness of the ceiling, recording each painted border before approving a restrained restoration.','修复人员记录了天花板装饰的繁复程度，在批准克制的修复方案前逐一拍下彩绘边饰。','The conservator documented the elaborateness of the ceiling / recording each painted border / before approving a restrained restoration.','elaborateness 作 documented 的宾语；of 短语说明装饰复杂的对象。','逐一记录彩绘边饰是在衡量装饰细节的繁复程度。'),'The elaborateness of the undecorated ceiling came from its complete lack of detail.','The simplicity of the undecorated ceiling came from its complete lack of detail.','没有装饰细节体现简洁，不体现繁复。','meaning',[q('elaborateness',1,1,'The elaborateness of a design refers to its?',['degree of detail or ornament','age in years','weight in kilograms'],'degree of detail or ornament','elaborateness.s1 指繁复、精细的程度。'),q('elaborateness',2,1,'A critic might praise the elaborateness of?',['a tapestry woven with many intricate scenes','a blank sheet with no pattern','a plain box with smooth unmarked sides'],'a tapestry woven with many intricate scenes','丰富细节和图案体现繁复。'),q('elaborateness',3,1,'Elaborateness is related most closely to?',['elaborate','elastic','election'],'elaborate','elaborateness 由 elaborate 派生。'),q('elaborateness',4,1,'A simple design has low elaborateness when it?',['uses few details or ornaments','contains thousands of tiny patterns','covers every surface with carving'],'uses few details or ornaments','细节少说明繁复程度低。')]);

put('elaboration','elaboration 由 elaborate 加名词后缀 -ion 构成；可指把说明说得更详尽，也可指复杂精细的成品或版本。',c('elaboration.s1','学术写作','The reviewer requested an elaboration of the method, asking the authors to explain how participants were selected and measured.','审稿人要求进一步详述方法，请作者解释参与者如何入选以及如何接受测量。','The reviewer requested an elaboration of the method / asking the authors to explain / how participants were selected and measured.','elaboration 作 requested 的宾语；of the method 指需要补充说明的主题。','审稿人要更多方法细节，体现 elaboration.s1 的说明义。'),'The editor asked for an elaboration, meaning the authors should delete all details and provide less explanation.','The editor asked for a summary, meaning the authors should reduce the explanation.','elaboration 增加细节；删减解释更接近 summary。','meaning',[q('elaboration',1,1,'A request for elaboration asks a writer to?',['explain an idea in greater detail','remove every supporting fact','change the topic completely'],'explain an idea in greater detail','elaboration.s1 指进一步详述。'),q('elaboration',2,2,'An elaboration can also be?',['a carefully developed or intricate version','a missing item that was never made','a short pause in a speech'],'a carefully developed or intricate version','elaboration.s2 指精细做成的版本或东西。'),q('elaboration',3,1,'Which reply is an elaboration of “the test failed”?',['The test failed because the sensor was miscalibrated and the control group was incomplete.','Yes.','The sky is blue.'],'The test failed because the sensor was miscalibrated and the control group was incomplete.','补充原因和细节是在详述原结论。'),q('elaboration',4,2,'An elaboration of an architectural model might include?',['a more intricate version with added structural detail','a blank page replacing the model','a list of unrelated dates'],'a more intricate version with added structural detail','精心细化的模型属于 elaboration.s2。')]);

put('elated','elated 源自拉丁语 elatus“高举、提升”，是 elate 的过去分词形容词；指因成功或好消息而非常高兴、得意。',c('elated.s1','竞赛结果','The team was elated when the judges announced its design had won, and members immediately called the volunteers who helped build it.','评委宣布团队的设计获胜时，大家欣喜若狂，马上给帮忙制作的志愿者打了电话。','The team was elated when the judges announced its design had won / and members immediately called the volunteers / who helped build it.','elated 作 was 的表语形容词；when 从句给出喜悦的原因。','获奖喜讯引发强烈愉悦，符合 elated.s1。'),'The team felt elated when the judges rejected its entry and ended the competition early.','The team felt disappointed when the judges rejected its entry and ended the competition early.','作品被拒并提前出局通常令人失望，不会使团队欣喜。','meaning',[q('elated',1,1,'Someone who feels elated is?',['extremely happy or proud','quietly confused','physically exhausted only'],'extremely happy or proud','elated.s1 指因成功或好消息而兴高采烈。'),q('elated',2,1,'Which news would most likely leave a student elated?',['being accepted into a highly desired program','losing an important application','having a broken pencil'],'being accepted into a highly desired program','获得期待已久的录取通知会令人欣喜。'),q('elated',3,1,'Elated is stronger than merely?',['pleased','uncertain','hungry'],'pleased','elated 表示程度很高的快乐或得意。'),q('elated',4,1,'Which sentence uses elated naturally?',['She was elated by the unexpected promotion.','She elated the cup onto the shelf.','The elated of the plan was written.'],'She was elated by the unexpected promotion.','elated 是描述人的形容词，常与 be 或 feel 连用。')]);

put('elation','elation 源自拉丁语 elatio“高举、振奋”，与 elate 同源；指因成功或好消息产生的强烈快乐和兴奋。',c('elation.s1','科学发现','A sense of elation spread through the laboratory when the final trial confirmed the result that the team had pursued for months.','最后一次试验证实了团队追寻数月的结果时，实验室里顿时充满了喜悦和兴奋。','A sense of elation spread through the laboratory / when the final trial confirmed the result / that the team had pursued for months.','elation 作介词 of 的宾语；when 从句说明喜悦出现的契机。','长期研究得到证实带来强烈欢欣，符合 elation。'),'The announcement brought elation because it confirmed the project had failed and everyone had lost their work.','The announcement brought grief because it confirmed the project had failed and everyone had lost their work.','项目失败和失业是悲痛的理由，与 elation 的欢喜相反。','meaning',[q('elation',1,1,'Elation is a feeling of?',['great happiness and excitement','mild thirst','careful suspicion'],'great happiness and excitement','elation.s1 指强烈的快乐与兴奋。'),q('elation',2,1,'A runner might feel elation after?',['winning a race after months of training','being told the race was cancelled after a loss','forgetting how to start'],'winning a race after months of training','训练后获胜会带来兴奋和喜悦。'),q('elation',3,1,'Elation is most likely to follow?',['success or welcome news','a routine neutral observation','a minor spelling correction'],'success or welcome news','成功和好消息是 elation 常见诱因。'),q('elation',4,1,'Which phrase is natural?',['a wave of elation','a measurement of elation in kilograms','the elation button on a door'],'a wave of elation','a wave of elation 是常见表达，指喜悦涌现。')]);

put('election','election 由 elect 加名词后缀 -ion 构成；elect 源自拉丁语 eligere“选出”；可指投票过程，也可指某人经投票当选这一事实。',c('election.s1','地方政治','The election drew a large turnout after both candidates held public debates and published detailed plans for local transport.','两位候选人举行公开辩论并公布本地交通的详细计划后，这场选举吸引了大量选民投票。','The election drew a large turnout / after both candidates held public debates / and published detailed plans for local transport.','election 作主语；turnout 指参加投票的人数。','候选人竞选并由选民投票决定职位，体现 election.s1。'),'The election was a private appointment made by one official without a vote.','The appointment was a private decision made by one official without a vote.','没有投票、由一人任命不是 election.s1 的选举过程。','meaning',[q('election',1,1,'An election is an organized process in which people?',['vote to choose someone for office','repair a public road','take a scientific measurement'],'vote to choose someone for office','election.s1 指投票选举职位。'),q('election',2,2,'Her election to the council refers to?',['the fact that voters chose her','the room where ballots were printed','her decision to leave the council'],'the fact that voters chose her','election.s2 指经投票当选这一事实。'),q('election',3,1,'A high turnout at an election means?',['many eligible voters participated','no one received a ballot','the candidates withdrew before voting'],'many eligible voters participated','turnout 高表示参与投票的人多。'),q('election',4,1,'Which event is an election?',['citizens cast ballots for a mayor','a manager appoints a deputy alone','a board repairs its office'],'citizens cast ballots for a mayor','选民投票选市长属于选举。')]);

put('elective','elective 由 elect 加形容词后缀 -ive 构成；可表示可自由选择的课程，也可指由选举产生而非任命的职位。',c('elective.s2','大学课程','Because the degree requires several core subjects, Mina used her remaining credits for an elective in environmental history.','由于学位要求修读几门核心课程，米娜把剩余学分用于选修环境史。','Because the degree requires several core subjects / Mina used her remaining credits / for an elective in environmental history.','elective 作介词 for 的宾语，指可选修的课程；because 引出选课背景。','学生可自行选择环境史课程，体现 elective.s2。'),'The student had to take the elective because it was compulsory for every degree.','The student chose an optional course because it was not required for the degree.','所有学生必须修读的是必修课；elective.s2 是可选择的课程。','meaning',[q('elective',1,2,'An elective course is one that a student?',['may choose but is not required to take','must take as a universal requirement','cannot enroll in under any circumstances'],'may choose but is not required to take','elective.s2 指选修课。'),q('elective',2,1,'An elective public office is filled by?',['a vote rather than an appointment','a lottery among buildings','a weather report'],'a vote rather than an appointment','elective.s1 可指由选举产生的职位。'),q('elective',3,2,'A student choosing an elective is selecting?',['one option from available courses','a mandatory course assigned to everyone','a textbook’s page number'],'one option from available courses','选修课允许学生在课程中选择。'),q('elective',4,1,'Which phrase uses elective in the political sense?',['an elective council position','an elective chapter in a novel','an elective rainstorm'],'an elective council position','由投票产生的职位可以称 elective。')]);

put('electric','electric 源自新拉丁语 electricus“像琥珀吸引物体的”，来自希腊语 ēlektron“琥珀”；可指电力驱动，也可形容紧张兴奋的气氛。',c('electric.s1','家用设备','The electric kettle shut itself off when the water boiled, allowing the family to make tea without watching the stove.','水烧开后电热水壶自动断电，让一家人不用看着炉灶也能泡茶。','The electric kettle shut itself off / when the water boiled / allowing the family / to make tea without watching the stove.','electric 修饰 kettle，表示以电力工作的设备；when 引出触发条件。','水壶靠电力加热且自动断电，体现 electric.s1。'),'The electric kettle was heated only by a wood fire and had no electrical parts.','The traditional kettle was heated by a wood fire and had no electrical parts.','仅由木柴加热、没有电路的壶不是 electric kettle。','meaning',[q('electric',1,1,'An electric heater gets its operating power from?',['electricity','wind-up gears alone','burning paper inside the room'],'electricity','electric.s1 指由电力驱动的。'),q('electric',2,2,'An electric atmosphere at a concert feels?',['charged with excitement and tension','silent and emotionally flat','wet from heavy rain'],'charged with excitement and tension','electric.s2 比喻气氛兴奋、紧张。'),q('electric',3,1,'Which device is electric?',['a lamp powered from a wall outlet','a hand mirror with no circuit','a stone used as a paperweight'],'a lamp powered from a wall outlet','插电工作的灯具属于 electric device。'),q('electric',4,2,'A crowd is described as electric just before a final when it is?',['intensely excited and expectant','completely unaware of the event','quiet because no one is present'],'intensely excited and expectant','赛前兴奋期待的气氛体现 electric.s2。')]);

put('electrical','electrical 由 electric 加 -al 构成，表示与电力、电路、布线或电工工作有关；它本身通常不表示某物一定由电驱动。',c('electrical.s2','建筑维修','The contractor inspected the electrical wiring before installing the new lights, checking that the circuits met local safety codes.','承包商在安装新灯前检查电线，确认线路符合当地安全规范。','The contractor inspected the electrical wiring / before installing the new lights / checking that the circuits met local safety codes.','electrical 修饰 wiring，说明线路工作和电工系统相关。','检查布线和电路规范属于 electrical.s2 的电工、布线义。'),'The electrical repair was completed without touching the wires, circuits, or any related equipment.','The cosmetic repair was completed without touching the wires, circuits, or any related equipment.','完全未涉及电线或电路的修补不属于电气维修。','meaning',[q('electrical',1,1,'Electrical engineering concerns?',['electricity and its applications','the study of ancient poetry only','the cultivation of fruit trees'],'electricity and its applications','electrical.s1 指与电有关的。'),q('electrical',2,2,'An electrical contractor commonly works on?',['wiring and electrical systems','roof gardens and soil only','book indexes and citations'],'wiring and electrical systems','electrical.s2 指电工或布线方面。'),q('electrical',3,1,'Which item is electrical equipment?',['a circuit breaker','a wool scarf','a wooden spoon'],'a circuit breaker','断路器属于电路设备。'),q('electrical',4,2,'An electrical inspection might check whether?',['building wiring meets safety rules','a poem has a regular rhyme','a garden receives enough sunlight'],'building wiring meets safety rules','电气检查会核对布线和安全规范。')]);

put('electrically','electrically 由 electrical 加副词后缀 -ly 构成，表示以电为动力、通过电路或电子信号来完成。',c('electrically.s1','交通技术','The old bus was converted to run electrically, so batteries now power its motor instead of a diesel engine.','这辆旧公交车改为电力驱动，如今由电池为电动机供能，而不再使用柴油发动机。','The old bus was converted to run electrically / so batteries now power its motor / instead of a diesel engine.','electrically 修饰 run，说明车辆的动力来源；so 引出改造后的结果。','电池给电动机供电，体现 electrically.s1。'),'The bus ran electrically using a tank of diesel and no battery or motor.','The bus ran on diesel using a fuel tank and an internal-combustion engine.','柴油燃烧驱动、没有电动系统不属于 electrically 驱动。','meaning',[q('electrically',1,1,'A device powered electrically uses?',['electricity as its power source','only gravity with no energy supply','a handwritten instruction'],'electricity as its power source','electrically.s1 指靠电力运行。'),q('electrically',2,1,'A train connected electrically to an overhead line receives?',['electric power through the line','water through a pipe','fuel through a paper ticket'],'electric power through the line','架空线通过电路给列车供电。'),q('electrically',3,1,'Which vehicle runs electrically?',['a battery-powered car','a horse-drawn carriage','a sailboat moved only by wind'],'a battery-powered car','电池为电机供能的汽车属于电驱动。'),q('electrically',4,1,'Electrically is an adverb modifying?',['how a machine is powered or operates','the shape of a machine’s paint','who bought the machine'],'how a machine is powered or operates','副词表示设备通过电力工作的方式。')]);

put('electrician','electrician 由 electric 加表示职业或专长的 -ian 构成；指安装、检修布线或电气系统的专业人员。',c('electrician.s1','住宅维修','The electrician isolated the circuit, replaced the damaged socket, and tested it before restoring power to the kitchen.','电工先切断该线路，更换损坏插座，并在恢复厨房供电前进行测试。','The electrician isolated the circuit / replaced the damaged socket / and tested it / before restoring power to the kitchen.','electrician 是并列谓语的共同主语；before 从句说明恢复供电前的安全步骤。','隔离电路、修插座并检测是电工的安装维修工作。'),'The electrician repaired the leaking roof by replacing broken tiles and sealing the chimney.','The roofer repaired the leaking roof by replacing broken tiles and sealing the chimney.','修屋顶主要是屋面工的工作，与电工的电气专业不同。','meaning',[q('electrician',1,1,'An electrician is trained to work on?',['wiring and electrical systems','the growth of forest trees','the editing of film subtitles only'],'wiring and electrical systems','electrician.s1 指安装检修电气线路的人。'),q('electrician',2,2,'An electrical engineer or technician may specialize in?',['electrical systems and equipment','ancient handwriting only','soil drainage only'],'electrical systems and equipment','electrician.s2 指电气系统领域的技术人员。'),q('electrician',3,1,'Who should inspect unsafe household wiring?',['a qualified electrician','a visitor with no training','a painter chosen for wall color'],'a qualified electrician','电路安全检查应交由合格电工。'),q('electrician',4,1,'The suffix -ian in electrician indicates?',['a person associated with a field or occupation','a machine that produces electricity','a past tense verb'],'a person associated with a field or occupation','-ian 可表示某领域的人员。')]);

put('electrify','electrify 由 electric 加动词后缀 -ify 构成，可指使设备通电、把系统改为电力驱动，也可指使人兴奋激动。',c('electrify.s2','音乐现场','The singer’s unexpected encore electrified the audience, and people who had been sitting quietly leapt up to dance.','歌手意外返场使观众兴奋起来，原本安静坐着的人纷纷起身跳舞。','The singer’s unexpected encore electrified the audience / and people who had been sitting quietly / leapt up to dance.','electrify 以 audience 为宾语，作比喻义“使兴奋”；and 连接现场反应。','听众从安静转为欢呼起舞，体现 electrify.s2。'),'The encore electrified the audience by making every listener bored and eager to leave.','The encore exhausted the audience by making every listener bored and eager to leave.','令人厌倦、急于离场不是使人兴奋的效果。','meaning',[q('electrify',1,1,'To electrify a fence is to?',['make it carry an electric charge','cover it with dry leaves','turn it into a river'],'make it carry an electric charge','electrify.s1 可指使物体带电。'),q('electrify',2,2,'A thrilling announcement can electrify a crowd by?',['exciting it intensely','making everyone fall asleep','removing all sound from the room'],'exciting it intensely','electrify.s2 比喻使人强烈兴奋。'),q('electrify',3,1,'A railway is electrified when it is?',['converted to use electric power','closed to all trains permanently','painted with bright colors'],'converted to use electric power','铁路电气化指改用电力牵引。'),q('electrify',4,2,'Which event might electrify sports fans?',['a last-second winning goal','a routine notice that the doors are open','a blank scoreboard with no game'],'a last-second winning goal','惊险绝杀会令球迷群情振奋。')]);

put('electro','electro 源自 electrum“琥珀”相关的 electric 系词族；在工艺中作名词，指通过电沉积制成的金属版或电铸件。',c('electro.s1','印刷工艺','The printer made an electro of the engraved image by depositing metal onto a prepared mould, then used the durable plate for repeated impressions.','印刷工把金属电沉积到制好的模具上，为雕刻图像制作电铸版，随后用这块耐用版反复印刷。','The printer made an electro of the engraved image / by depositing metal onto a prepared mould / then used the durable plate / for repeated impressions.','electro 作 made 的宾语；by depositing 说明电铸版的制作方法。','电沉积形成可重复印刷的金属版，符合 electro.s1。'),'The printer called a paper sketch an electro even though no metal had been deposited and no plate existed.','The printer called the metal plate an electro after producing it by electrodeposition.','只有纸上草图、没有电沉积金属版，不符合该专业义。','meaning',[q('electro',1,1,'In a printing workshop, an electro is?',['a metal plate or object made by electrodeposition','a paper label for a book','a type of electric lamp'],'a metal plate or object made by electrodeposition','electro.s1 指电沉积制作的金属版或物件。'),q('electro',2,1,'How is an electro plate formed?',['metal is deposited onto a prepared mould','wood is dissolved in rainwater','ink is drawn with a pencil only'],'metal is deposited onto a prepared mould','电沉积将金属附着在模具上。'),q('electro',3,1,'A printer values an electro because it can?',['make repeated impressions from a durable plate','replace every sheet of paper','produce electricity for a whole town'],'make repeated impressions from a durable plate','耐用电铸版可反复压印。'),q('electro',4,1,'Which object is not an electro in this craft sense?',['an uncoated paper drawing with no metal plate','a metal copy made on a mould','a durable electrodeposited printing plate'],'an uncoated paper drawing with no metal plate','纸上图画没有电铸金属层，不是 electro。')]);

put('electrocardiogram','electrocardiogram 由 electro-“电”、cardio-“心脏”和 -gram“记录”构成；指显示心脏电活动的描记图，常缩写 ECG 或 EKG。',c('electrocardiogram.s1','临床检查','The nurse attached small electrodes to the patient’s chest and printed an electrocardiogram to check the rhythm before the procedure.','护士把小电极贴在患者胸部，并打印心电图，以便手术前检查心律。','The nurse attached small electrodes to the patient’s chest / and printed an electrocardiogram / to check the rhythm before the procedure.','electrocardiogram 作 printed 的宾语；to check 表示检查的目的。','心电图记录心脏电活动并用于观察节律，符合该词义。'),'The electrocardiogram recorded the patient’s bone density and showed no heart activity.','The bone-density scan recorded the patient’s bones, while the electrocardiogram recorded heart activity.','心电图记录心脏电信号，不用于测量骨密度。','meaning',[q('electrocardiogram',1,1,'An electrocardiogram records electrical activity from the?',['heart','liver’s color','bones of the foot'],'heart','electrocardiogram.s1 是心脏电活动的记录图。'),q('electrocardiogram',2,1,'A clinician may use an electrocardiogram to examine?',['heart rhythm','hair growth','the temperature of a room'],'heart rhythm','心电图可显示心律。'),q('electrocardiogram',3,1,'Which abbreviation commonly refers to an electrocardiogram?',['ECG','GPS','DNA'],'ECG','electrocardiogram 常缩写为 ECG。'),q('electrocardiogram',4,1,'The element cardio- in electrocardiogram means?',['heart','earth','sound'],'heart','cardio- 表示心脏。')]);

put('electrode','electrode 由 electro-“电”与 -ode“通道、路径”构成，经法拉第术语体系进入科学英语；指与电路连接并接触非金属介质的导体。',c('electrode.s1','电化学实验','The researcher placed one electrode in each side of the electrolyte so current could pass through the solution and trigger the reaction.','研究人员在电解质两侧各放置一个电极，使电流穿过溶液并触发反应。','The researcher placed one electrode in each side of the electrolyte / so current could pass through the solution / and trigger the reaction.','electrode 作 placed 的宾语；so 引出电极布置所实现的功能。','电极与电解质接触，使电流进入或离开非金属介质。'),'The electrode never contacted the electrolyte, so it could not pass current into the solution.','The electrode contacted the electrolyte, so current could pass into the solution.','删除 never 后，电极与电解质接触，符合电极传导电流的功能。','meaning',[q('electrode',1,1,'An electrode is a conductor that?',['makes electrical contact with a medium in a circuit','stores printed text on paper','measures an object’s age'],'makes electrical contact with a medium in a circuit','electrode.s1 指电路中与介质接触的导体。'),q('electrode',2,1,'Where might electrodes be placed in electrolysis?',['in contact with the electrolyte','inside a wooden bookcase with no circuit','on a cloud far from the apparatus'],'in contact with the electrolyte','电极需要和电解质接触以传导电流。'),q('electrode',3,1,'Which device uses electrodes to detect body signals?',['an electrocardiograph','a paper ruler','a dry paintbrush'],'an electrocardiograph','心电设备通过电极接触皮肤获取信号。'),q('electrode',4,1,'The prefix electro- in electrode relates to?',['electricity','plants','distance'],'electricity','electro- 与电有关。')]);

put('electroencephalogram','electroencephalogram 由 electro-“电”、encephalo-“脑”和 -gram“记录”构成；指从头皮记录脑部电信号所得的图形，常缩写 EEG。',c('electroencephalogram.s1','神经检查','During the sleep study, sensors recorded an electroencephalogram so the clinician could compare brain-wave patterns across different stages.','睡眠研究期间，传感器记录了脑电图，供临床人员比较不同阶段的脑电波模式。','During the sleep study / sensors recorded an electroencephalogram / so the clinician could compare brain-wave patterns / across different stages.','electroencephalogram 作 recorded 的宾语；so 从句说明记录的用途。','头皮传感器记录并比较脑电活动，符合 EEG 的定义。'),'The electroencephalogram measured the patient’s blood-sugar level and ignored the brain’s electrical signals.','The blood test measured the patient’s blood-sugar level, while the electroencephalogram recorded brain signals.','血糖检测与脑电记录是不同检查；该图记录脑电活动。','meaning',[q('electroencephalogram',1,1,'An electroencephalogram records electrical signals associated with the?',['brain','stomach lining only','bones of the hand'],'brain','electroencephalogram.s1 指脑电图。'),q('electroencephalogram',2,1,'A sleep clinic may examine an EEG to study?',['patterns of brain activity during sleep','the color of a patient’s eyes','the speed of blood in a garden hose'],'patterns of brain activity during sleep','EEG 能记录睡眠中的脑电活动。'),q('electroencephalogram',3,1,'Which abbreviation commonly stands for electroencephalogram?',['EEG','ECG','ATM'],'EEG','脑电图常缩写为 EEG。'),q('electroencephalogram',4,1,'The part encephalo- in the word refers to the?',['brain','heart','skin'],'brain','encephalo- 表示脑。')]);

put('electrolysis','electrolysis 由 electro-“电”与希腊语 lysis“分解、松解”构成；指电流通过电解质引起化合物分解的过程。',c('electrolysis.s1','化学实验','In the demonstration, electrolysis separated water into hydrogen and oxygen as an electric current passed through the solution.','演示中，电流通过溶液时，电解过程将水分解为氢和氧。','In the demonstration / electrolysis separated water into hydrogen and oxygen / as an electric current passed through the solution.','electrolysis 作主语；as 从句说明分解发生时电流通过溶液。','电流通过电解质促成水的化学分解，体现 electrolysis.s1。'),'The electrolysis separated the compound by freezing it without any electric current or electrolyte.','The freezing separated the compound by cooling it without any electric current or electrolyte.','没有电流和电解质的冷冻过程不是电解。','meaning',[q('electrolysis',1,1,'Electrolysis uses an electric current to?',['decompose a compound in an electrolyte','freeze every solution instantly','measure the length of a wire'],'decompose a compound in an electrolyte','electrolysis.s1 指电流引起化合物分解。'),q('electrolysis',2,1,'Which setup could perform electrolysis?',['electrodes connected to a power source in an electrolyte','a sealed dry jar with no circuit','a wooden ruler placed in sunlight'],'electrodes connected to a power source in an electrolyte','电解需要电路、电极和电解质。'),q('electrolysis',3,1,'The suffix lysis in electrolysis conveys?',['breaking down or decomposition','measurement of weight','movement toward the north'],'breaking down or decomposition','lysis 表示分解、松解。'),q('electrolysis',4,1,'If a current causes water to form gases, the process is?',['electrolysis','condensation','sedimentation'],'electrolysis','电流引起水分解属于电解。')]);

put('electromagnet','electromagnet 由 electro-“电”与 magnet“磁铁”组成；指电流通过线圈时产生磁性的磁体，断电后磁性通常减弱或消失。',c('electromagnet.s1','工程控制','The crane switched on its electromagnet to lift scrap steel, then released the load by cutting the current to the coil.','起重机打开电磁铁吊起废钢，随后切断线圈电流以放下货物。','The crane switched on its electromagnet to lift scrap steel / then released the load / by cutting the current to the coil.','electromagnet 作 switched on 的宾语；by 短语说明释放货物的方法。','通电吸起钢料、断电放下，体现电磁铁由电流产生磁力。'),'The crane increased current to release the steel held by its electromagnet.','The crane cut current to release the steel held by its electromagnet.','增加线圈电流会增强吸力；切断电流才可释放所吊钢料。','meaning',[q('electromagnet',1,1,'An electromagnet becomes magnetic when?',['electric current flows through its coil','it is painted a bright color','it is placed beside a paper label'],'electric current flows through its coil','electromagnet.s1 的磁性由线圈电流产生。'),q('electromagnet',2,1,'How can a crane release steel held by an electromagnet?',['switch off the current','add more current indefinitely','freeze the steel in water'],'switch off the current','断电后电磁铁磁力通常减弱，货物可释放。'),q('electromagnet',3,1,'What makes an electromagnet useful in a scrapyard?',['its magnetism can be controlled electrically','it works only on wooden objects','it permanently glues metal together'],'its magnetism can be controlled electrically','电磁铁可通断控制，适合抓取和释放金属。'),q('electromagnet',4,1,'An electromagnet differs from a simple permanent magnet because it?',['uses current to create a controllable magnetic field','contains no magnetic effect','is made from paper only'],'uses current to create a controllable magnetic field','电磁铁靠电流产生可控磁场。')]);

// A28 checkpoint 3 complete

put('electromagnetic','electromagnetic 由 electro-“电”、magnet“磁”和 -ic 构成，表示同时涉及电与磁的；常用于 electromagnetic field、radiation 等科学搭配。',c('electromagnetic.s1','物理课堂','The antenna converted an electromagnetic signal into a current that the receiver could process and display as sound.','天线把电磁信号转换成电流，接收器随后处理该电流并将其显示为声音。','The antenna converted an electromagnetic signal into a current / that the receiver could process / and display as sound.','electromagnetic 修饰 signal；that 从句说明接收器处理该信号转换出的电流。','信号涉及电与磁的传播，体现 electromagnetic.s1。'),'The electromagnetic field involved magnetism but had no connection to electric charge or current.','The magnetic field involved magnetism but had no connection to an electric signal.','electromagnetic 指电与磁相关；排除电因素后不能称为电磁。','meaning',[q('electromagnetic',1,1,'An electromagnetic wave involves?',['both electric and magnetic effects','only a chemical smell','a purely mechanical rope'],'both electric and magnetic effects','electromagnetic.s1 表示涉及电与磁的。'),q('electromagnetic',2,1,'Which is an electromagnetic phenomenon?',['radio waves carrying a signal','a stone resting without a field','a handwritten note on a desk'],'radio waves carrying a signal','无线电波属于电磁辐射。'),q('electromagnetic',3,1,'An electromagnetic field connects concepts of?',['electricity and magnetism','botany and grammar','sound and taste only'],'electricity and magnetism','electromagnetic combines electric and magnetic.'),q('electromagnetic',4,1,'Which phrase is scientifically natural?',['electromagnetic radiation','electromagnetic wooden spoon','electromagnetic silence as a food'],'electromagnetic radiation','电磁辐射是常见科学搭配。')]);

put('electromagnetism','electromagnetism 由 electro-“电”、magnet“磁”与 -ism 构成；既指电流产生磁性的现象，也指研究电和磁关系的物理学领域。',c('electromagnetism.s1','物理史','The lecture traced the development of electromagnetism, explaining how experiments revealed that changing magnetic fields can induce electric currents.','讲座回顾了电磁学的发展，说明实验如何揭示变化的磁场能够感生电流。','The lecture traced the development of electromagnetism / explaining how experiments revealed / that changing magnetic fields can induce electric currents.','electromagnetism 作介词 of 的宾语；现在分词短语概述该学科讨论的联系。','磁场变化与电流感应的相互关系属于电磁现象和电磁学。'),'The course on electromagnetism studied only plant roots and excluded all electric and magnetic effects.','The course on botany studied plant roots and excluded electric and magnetic effects.','完全不研究电和磁的课程不属于电磁学。','meaning',[q('electromagnetism',1,1,'Electromagnetism studies the relationship between?',['electricity and magnetism','poetry and painting','soil and rainfall'],'electricity and magnetism','electromagnetism.s1 指电与磁的关系及相关物理学。'),q('electromagnetism',2,1,'A wire’s magnetic field when current flows is an example of?',['electromagnetism','photosynthesis','erosion'],'electromagnetism','电流产生磁场是电磁现象。'),q('electromagnetism',3,1,'Which topic belongs in a course on electromagnetism?',['induction of current by a changing magnetic field','classification of bird feathers','the grammar of ancient poems'],'induction of current by a changing magnetic field','电磁感应是电磁学的重要内容。'),q('electromagnetism',4,1,'The word combines ideas related to?',['electricity, magnetism, and a field of study','farming, cooking, and music','distance, time, and color'],'electricity, magnetism, and a field of study','electro-, magnet 与 -ism 构成该学科名。')]);

put('electronic','electronic 由 electron“电子”加 -ic 构成；可表示使用电子电路或设备，也可指通过计算机完成、无纸化的。',c('electronic.s2','银行服务','The bank sent an electronic statement to each customer’s secure account, so no paper copy was needed for the monthly record.','银行把电子对账单发送到每位客户的安全账户，因此月度记录不需要纸质副本。','The bank sent an electronic statement to each customer’s secure account / so no paper copy was needed / for the monthly record.','electronic 修饰 statement；so 从句说明数字发送带来的无纸化结果。','对账单通过计算机账户发送，无需纸本，体现 electronic.s2。'),'The bank mailed an electronic statement as a paper letter printed and delivered by hand.','The bank mailed a paper statement as a letter printed and delivered by hand.','手工打印并邮寄的纸本不是无纸化的 electronic statement。','meaning',[q('electronic',1,1,'An electronic device uses?',['electronic circuits or components','only a wooden lever','no mechanism of any kind'],'electronic circuits or components','electronic.s1 指使用电子电路的。'),q('electronic',2,2,'An electronic ticket is usually?',['stored or delivered digitally rather than on paper','a handwritten leaf collected from a tree','a metal tool for cutting wire'],'stored or delivered digitally rather than on paper','electronic.s2 指计算机方式、无纸化的。'),q('electronic',3,1,'Which object is electronic?',['a digital thermometer with a circuit','a clay bowl','an unmarked stone'],'a digital thermometer with a circuit','带有电子电路的温度计属于电子设备。'),q('electronic',4,2,'A company sends an electronic invoice when it?',['delivers the bill digitally','prints it only on paper and mails it','writes the amount on a wall'],'delivers the bill digitally','数字发送的账单体现 electronic 的无纸化义。')]);

put('electronically','electronically 由 electronic 加副词后缀 -ally 构成，表示用电子电路、计算机或电子信号完成某事。',c('electronically.s1','身份核验','Visitors can sign in electronically at the reception desk, where a tablet sends their names directly to the security system.','访客可以在接待处用电子方式登记，平板会把姓名直接发送到安保系统。','Visitors can sign in electronically at the reception desk / where a tablet sends their names / directly to the security system.','electronically 修饰 sign in；where 从句说明登记设备如何连接系统。','通过平板登记并传输数据，符合 electronically.s1。'),'The visitors signed in electronically by carving their names into a wooden desk with a knife.','The visitors signed in manually by carving their names into a wooden desk with a knife.','用刀刻写是手动方式，不是通过电子设备完成。','meaning',[q('electronically',1,1,'To file a form electronically is to?',['submit it using a computer or digital system','bury it in the ground','read it aloud without recording it'],'submit it using a computer or digital system','electronically.s1 指用计算机或电子系统完成。'),q('electronically',2,1,'A sensor can monitor a machine electronically by?',['sending signals through electronic equipment','asking a visitor to guess its temperature','painting the machine blue'],'sending signals through electronic equipment','电子传感器以信号监测机器。'),q('electronically',3,1,'Which action is done electronically?',['paying a bill through a secure online account','handing over coins at a counter','writing a check with a pen'],'paying a bill through a secure online account','通过网上账户付款属于电子方式。'),q('electronically',4,1,'Electronically is an adverb related to?',['electronic equipment or signals','physical height','a person’s family name'],'electronic equipment or signals','electronically 来源于 electronic。')]);

put('electronics','electronics 由 electronic 加 -ics 构成，可指研究电子电路的科学与工程，也可泛指电子设备这一类产品。',c('electronics.s1','工程教育','The course in electronics taught students to read circuit diagrams, solder components, and test how signals changed across a board.','电子学课程教学生读电路图、焊接元件，并测试信号在电路板上的变化。','The course in electronics taught students / to read circuit diagrams / solder components / and test how signals changed across a board.','electronics 作介词 in 的宾语，指学科；taught 后并列三个不定式内容。','电路图、元件和信号处理属于 electronics.s1 学科内容。'),'Her course in electronics focused exclusively on poetry meter and never mentioned circuits.','Her course in literary studies focused on poetry meter and never mentioned circuits.','诗歌格律属于文学研究，不是电子学课程内容。','meaning',[q('electronics',1,1,'Electronics as a field studies?',['electronic circuits and devices','ancient farming tools','the grammar of conversation'],'electronic circuits and devices','electronics.s1 指电子学领域。'),q('electronics',2,2,'A shop selling consumer electronics mainly sells?',['devices such as radios, phones, and televisions','fresh vegetables and grain','wooden furniture only'],'devices such as radios, phones, and televisions','electronics.s2 可泛指电子设备产品。'),q('electronics',3,1,'Which topic belongs to electronics?',['testing how a circuit carries a signal','identifying tree species by leaves','comparing the rhyme in poems'],'testing how a circuit carries a signal','电路信号测试属于电子学。'),q('electronics',4,2,'A box of electronics might contain?',['a phone and a digital radio','a sack of potatoes','a set of stone blocks'],'a phone and a digital radio','手机和数字收音机都是电子设备。')]);

put('elegy','elegy 源自希腊语 elegeia“哀歌”，经拉丁语与法语进入英语；尤指悼念逝者、表达悲哀的诗歌。',c('elegy.s1','诗歌阅读','The poet’s elegy remembered her brother through small domestic details, describing the chipped cup he used each morning.','诗人通过日常小事悼念哥哥，在挽歌中写到他每天早晨使用的缺口杯子。','The poet’s elegy remembered her brother through small domestic details / describing the chipped cup / he used each morning.','elegy 作主语；remembered 表明悼念对象，describing 补充诗中的细节。','诗歌回忆已故亲人并表达哀思，符合 elegy.s1。'),'The elegy celebrated the joyful opening of a shop with comic songs and no sadness or loss.','The opening song celebrated the joyful opening of a shop with comic songs and no sadness or loss.','喜庆开店、没有哀伤的歌曲不是悼念逝者的挽歌。','meaning',[q('elegy',1,1,'An elegy is a poem that often?',['mourns someone who has died','gives instructions for baking bread','lists train departure times'],'mourns someone who has died','elegy.s1 指挽歌，常悼念逝者。'),q('elegy',2,1,'Which subject suits an elegy?',['remembering a lost friend with sorrow','celebrating a comic victory','explaining how to repair a faucet'],'remembering a lost friend with sorrow','对逝去朋友的哀悼适合挽歌主题。'),q('elegy',3,1,'The tone of an elegy is most likely?',['reflective and sorrowful','purely technical and cheerful','a list of shopping prices'],'reflective and sorrowful','挽歌常有沉思和悲哀的语气。'),q('elegy',4,1,'A poem written in memory of a dead family member could be called?',['an elegy','a menu','a blueprint'],'an elegy','悼念逝者的诗歌属于 elegy。')]);

put('elemental','elemental 由 element 加 -al 构成；可指构成事物基础或本质的，也可指古代四元素观念及原始自然力量相关的。',c('elemental.s1','基础技能','The instructor treated clear observation as an elemental skill, teaching new researchers to record what they saw before proposing an explanation.','指导员把清晰观察视为一项基本技能，教新研究人员先记录所见，再提出解释。','The instructor treated clear observation as an elemental skill / teaching new researchers / to record what they saw / before proposing an explanation.','elemental 修饰 skill，表示基础且不可或缺；before 标明研究步骤。','观察是后续分析的基本组成部分，体现 elemental.s1。'),'The course treated arithmetic as an elemental skill no beginner ever needs to learn.','The course treated arithmetic as an advanced skill no beginner ever needs to learn.','基础技能不应被说成初学者完全不必学习。','meaning',[q('elemental',1,1,'An elemental part of a method is?',['basic and essential','an optional decoration','a result added after completion'],'basic and essential','elemental.s1 表示基本、本质的。'),q('elemental',2,1,'In older theories, elemental forces were connected with?',['the fundamental elements or raw powers of nature','modern office furniture','computer passwords only'],'the fundamental elements or raw powers of nature','elemental.s2 与古代元素观和自然力量有关。'),q('elemental',3,1,'Which is an elemental requirement for safe lab work?',['following basic protective procedures','guessing at chemical labels','ignoring emergency exits'],'following basic protective procedures','安全程序是实验室的基础要求。'),q('elemental',4,1,'Elemental is closest in one common sense to?',['fundamental','accidental','ornamental'],'fundamental','基本、本质的事物可称 elemental。')]);

put('elevation','elevation 由 elevate 加名词后缀 -ion 构成；elevate 源自拉丁语 elevare“抬高”；可指地点高度，也可指提升或提拔。',c('elevation.s1','地形测量','Because the campsite lies at an elevation of nearly three thousand metres, hikers were advised to spend a night acclimatizing nearby.','由于营地海拔近三千米，徒步者被建议先在附近住一晚以适应环境。','Because the campsite lies at an elevation of nearly three thousand metres / hikers were advised / to spend a night acclimatizing nearby.','elevation 作介词 at 的宾语，表示高出海平面的高度；because 引出适应建议的原因。','以米数描述营地高度，符合 elevation.s1。'),'The map recorded the mountain’s elevation as the number of people promoted that year.','The company recorded the managers’ elevation as the number of people promoted that year.','海拔是地点高度；人员晋升属于 elevation 的另一种抽象义。','meaning',[q('elevation',1,1,'A town’s elevation of 900 metres describes its?',['height above sea level','distance from a train station','population size'],'height above sea level','elevation.s1 指地点海拔或高度。'),q('elevation',2,2,'The elevation of an employee to director means?',['promotion to a higher position','measurement of the office ceiling','a move to a lower floor'],'promotion to a higher position','elevation.s2 指职位提升。'),q('elevation',3,1,'Which instrument helps determine a place’s elevation?',['a surveying altimeter','a kitchen timer','a color chart'],'a surveying altimeter','测高设备可测地点海拔。'),q('elevation',4,2,'A formal elevation ceremony might recognize?',['someone’s promotion or raised status','the height of a wave only','a drop in temperature'],'someone’s promotion or raised status','晋升仪式体现地位提升义。')]);

put('elicitation','elicitation 由 elicit 加名词后缀 -ation 构成；elicit 源自拉丁语 elicere“引出”，指通过提问或刺激引出原本未主动表达的信息或反应。',c('elicitation.s1','访谈研究','The interviewer used open questions for the elicitation of detailed memories, allowing participants to describe events in their own words.','访谈者使用开放式问题引出详细回忆，让参与者用自己的话描述经历。','The interviewer used open questions / for the elicitation of detailed memories / allowing participants / to describe events in their own words.','elicitation 作介词 for 的宾语；of 短语说明被引出的内容。','开放式提问使受访者说出详细回忆，体现 elicitation.s1。'),'The elicitation of the witness’s account meant preventing her from speaking or responding.','The suppression of the witness’s account meant preventing her from speaking or responding.','阻止证人表达是压制信息，不是把信息引出来。','meaning',[q('elicitation',1,1,'Elicitation is the process of?',['drawing out information or a response','hiding all available evidence','copying a report without reading it'],'drawing out information or a response','elicitation.s1 指引出信息、答案或反应。'),q('elicitation',2,1,'A researcher uses careful questions for elicitation to?',['encourage participants to share relevant details','make participants forget the topic','replace all answers with guesses'],'encourage participants to share relevant details','问题可引导受访者说出相关细节。'),q('elicitation',3,1,'Which activity is an elicitation of a response?',['asking a child what they think a picture shows','silencing the child before any question','discarding the picture without discussion'],'asking a child what they think a picture shows','提问并引出回答属于 elicitation。'),q('elicitation',4,1,'The root elicit means?',['draw out or bring forth','push away and conceal','weigh and measure'],'draw out or bring forth','elicitation 由 elicit 派生，表示引出。')]);

put('eligibility','eligibility 由 eligible 加名词后缀 -ity 构成；eligible 源自拉丁语 eligere“选出”，现代词指符合申请、投票或领取资格的状态。',c('eligibility.s1','奖学金申请','The scholarship committee checked each applicant’s eligibility against the published rules on income, residency, and course enrollment.','奖学金委员会依据公布的收入、居住地和课程注册规则，核查每位申请者是否符合资格。','The scholarship committee checked each applicant’s eligibility / against the published rules / on income, residency, and course enrollment.','eligibility 作 checked 的宾语；against 表示依据规则进行核对。','收入、居住和注册条件决定能否申请奖学金，符合 eligibility.s1。'),'The applicant’s eligibility was confirmed even though she failed every required condition.','The applicant’s ineligibility was confirmed because she failed every required condition.','未满足所有必要条件说明不具资格。','meaning',[q('eligibility',1,1,'Eligibility for a grant means?',['meeting the conditions to apply for or receive it','having already spent the grant','knowing the name of the committee'],'meeting the conditions to apply for or receive it','eligibility.s1 指具备申请或领取资格。'),q('eligibility',2,1,'A voter’s eligibility may depend on?',['meeting legal requirements such as age and registration','owning a particular color of car','being able to name every candidate'],'meeting legal requirements such as age and registration','法律规定的年龄和登记要求决定投票资格。'),q('eligibility',3,1,'Which document might establish eligibility for a program?',['proof that the applicant meets its stated criteria','an unrelated restaurant menu','a blank postcard with no name'],'proof that the applicant meets its stated criteria','符合标准的证明有助于核验资格。'),q('eligibility',4,1,'Eligibility is related to being?',['eligible','electric','elusive'],'eligible','eligibility 是 eligible 的名词形式。')]);

put('elimination','elimination 由 eliminate 加名词后缀 -ion 构成；可指彻底去除，也可指在竞赛中被淘汰、必须退出。',c('elimination.s2','淘汰赛','After the elimination of the defending champions, the semifinal field included four teams that had never reached this stage before.','卫冕冠军被淘汰后，半决赛中的四支球队此前都从未打到这一阶段。','After the elimination of the defending champions / the semifinal field included four teams / that had never reached this stage before.','elimination 作介词 after 的宾语；of 短语说明被淘汰的对象。','卫冕冠军失利后退出比赛，体现 elimination.s2。'),'The team’s elimination meant it won the tournament and advanced to the final.','The team’s advancement meant it won the semifinal and reached the final.','淘汰表示退出竞赛，不是赢得比赛并晋级。','meaning',[q('elimination',1,1,'The elimination of a pollutant means?',['removing it from the system','adding more of it','measuring its color'],'removing it from the system','elimination.s1 指去除、消除。'),q('elimination',2,2,'A team’s elimination from a tournament means it?',['is defeated and must leave the competition','wins the final automatically','changes its uniforms'],'is defeated and must leave the competition','elimination.s2 指被淘汰出局。'),q('elimination',3,1,'Which process is elimination of waste from water?',['filtering it out','pouring more waste in','renaming the water'],'filtering it out','过滤并去除废物体现消除义。'),q('elimination',4,2,'After elimination in a knockout round, a player usually?',['cannot continue in that competition','moves directly to the final','becomes the referee by rule'],'cannot continue in that competition','被淘汰后不能继续参加该轮比赛。')]);

put('elixir','elixir 经法语源自阿拉伯语 al-iksīr，历史上指炼金术液剂或被认为能治病、延寿的灵药；现代也可比喻神奇良方。',c('elixir.s1','医学史','The medieval manuscript described an elixir that alchemists believed could restore health, though the recipe offered no reliable evidence.','中世纪手稿描述了一种炼金术士相信能恢复健康的灵药，尽管配方没有提供可靠证据。','The medieval manuscript described an elixir / that alchemists believed could restore health / though the recipe offered no reliable evidence.','elixir 作 described 的宾语；that 从句描述其声称的功效，though 限定可信度。','历史文本中的治病、延寿液剂符合 elixir.s1。'),'The manuscript called plain drinking water an elixir proven to grant endless life, with no claim of special power.','The manuscript called the potion an elixir believed to grant long life, though the claim was unproven.','若没有任何特殊功效说法，就不能将普通水称作灵药。','meaning',[q('elixir',1,1,'An elixir in alchemical history was a liquid believed to?',['cure illness or prolong life','measure the height of a tree','freeze a metal tool'],'cure illness or prolong life','elixir.s1 指炼金术灵液或灵药。'),q('elixir',2,1,'A writer calling a tonic an elixir usually suggests it is?',['a remarkable or almost magical remedy','a routine piece of furniture','a device for telling time'],'a remarkable or almost magical remedy','elixir 也可比喻神奇良方。'),q('elixir',3,1,'Which phrase fits the historical sense of elixir?',['the alchemist’s supposed life-extending liquid','the carpenter’s wooden ruler','the sailor’s map of a coastline'],'the alchemist’s supposed life-extending liquid','历史词义是被认为有治病或延寿作用的液剂。'),q('elixir',4,1,'Modern evidence would treat claims of a life-giving elixir as?',['claims requiring proof, not established fact','automatically true because of the name','a measurement of distance'],'claims requiring proof, not established fact','灵药功效属于历史信念或比喻，不应当作已证事实。')]);

put('elk','elk 源自古英语 elch，经日耳曼语族而来；英式英语常指驼鹿，北美英语常指马鹿（wapiti），具体所指因地区而异。',c('elk.s1','野生动物辨识','The North American field guide identifies the elk as a wapiti, while a British guide uses elk for the larger moose found in northern forests.','北美野外指南把 elk 标作马鹿，而英国指南用 elk 指北方森林中更大的驼鹿。','The North American field guide identifies the elk as a wapiti / while a British guide uses elk / for the larger moose found in northern forests.','elk 作名词；while 对照不同地区对同一词的动物指称。','地区差异本身是该词使用要点，不能假定 elk 全球只指一种鹿。'),'The guide said elk always means the same species in every English-speaking region.','The guide noted that elk can refer to different deer by region.','elk 的指称在北美与英式英语中有所不同，并非各地一致。','meaning',[q('elk',1,1,'In North American usage, elk often refers to a?',['wapiti, a large deer','small tropical fish','domestic chicken'],'wapiti, a large deer','北美英语中 elk 常指马鹿。'),q('elk',2,1,'In British usage, elk often refers to a?',['moose','kangaroo','wild turkey'],'moose','英式英语常用 elk 指驼鹿。'),q('elk',3,1,'Why should a reader check the region when seeing elk?',['the word can name different deer in different varieties of English','the word is always a verb','the animal lives only in cities'],'the word can name different deer in different varieties of English','elk 的具体动物指称有地区差异。'),q('elk',4,1,'Which statement is accurate about elk?',['its reference varies between North American and British usage','it always means a fish','it names one bird species worldwide'],'its reference varies between North American and British usage','该词通常指鹿类，但所指种类因地区而异。')]);

put('ellipsis','ellipsis 源自希腊语 elleipsis“省略”，由 en- 与 leipein“留下、缺少”相关；指语法或语境可恢复信息的省略，也指表示省略的点号。',c('ellipsis.s1','英文写作','In the reply “I ordered the blue one,” an ellipsis leaves out the noun “shirt,” which the earlier question makes clear.','在回答“I ordered the blue one”中，省略结构没有重复名词“shirt”，因为前文问题已经说清楚。','In the reply “I ordered the blue one” / an ellipsis leaves out the noun “shirt” / which the earlier question makes clear.','ellipsis 作主语；which 从句解释被省略内容如何由上下文恢复。','名词未重复但可从前文补出，体现 ellipsis.s1。'),'The writer used ellipsis even though the missing noun was not recoverable from context.','The writer should repeat the noun because the context does not identify it.','Ellipsis is appropriate only when omitted material can be recovered from context.','meaning',[q('ellipsis',1,1,'In grammar, ellipsis is the?',['omission of words understood from context','repetition of every word twice','replacement of a noun with a number'],'omission of words understood from context','ellipsis.s1 指省略可从语境恢复的词。'),q('ellipsis',2,1,'A writer may mark omitted text with?',['three dots called an ellipsis','a question mark only','a comma after every letter'],'three dots called an ellipsis','ellipsis 也可指表示省略的点号。'),q('ellipsis',3,1,'Why is “I chose the red one” elliptical after a question about coats?',['the noun coat is understood and need not be repeated','the sentence has no verb','the color red is impossible to understand'],'the noun coat is understood and need not be repeated','前文已给出 coat，语境能补出被省略名词。'),q('ellipsis',4,1,'Which phrase best describes ellipsis?',['leaving out recoverable material','adding an unrelated paragraph','translating a word into another language'],'leaving out recoverable material','ellipsis 的核心是有根据地省略。')]);

put('elm','elm 源自古英语 elm，与古日耳曼语系同源词相关；名词指榆属树木，通常有锯齿状叶片和宽展树冠。',c('elm.s1','城市绿化','The council planted elm trees along the avenue, choosing disease-resistant varieties to restore shade lost when older trees died.','市政部门沿大道种下榆树，选用抗病品种，以恢复旧树死亡后失去的树荫。','The council planted elm trees along the avenue / choosing disease-resistant varieties / to restore shade / lost when older trees died.','elm 作 trees 的名词定语；不定式说明栽种目的。','树种、抗病品种和遮荫用途都对应 elm.s1。'),'The gardener planted an elm, a small annual herb that grows no trunk and dies after one week.','The gardener planted an elm, a large deciduous tree with a woody trunk.','elm 是树木，不是无树干的一年生草本。','meaning',[q('elm',1,1,'An elm is a kind of?',['tree','salt','small bird'],'tree','elm.s1 指榆树。'),q('elm',2,1,'Which feature may help identify an elm leaf?',['a serrated edge','a metal handle','a feathered surface'],'a serrated edge','榆树叶常有锯齿状叶缘。'),q('elm',3,1,'Where might a city plant elms?',['along a street to provide shade','inside a sealed water pipe','under a desk as stationery'],'along a street to provide shade','榆树可作城市行道树提供树荫。'),q('elm',4,1,'The plural of elm is?',['elms','elmies','elmen only'],'elms','elm 的常规复数形式为 elms。')]);

put('elongate','elongate 源自拉丁语 elongare“使变长”，由 e-“向外”与 longus“长”相关；作动词指拉长，也可作形容词指相对细长。',c('elongate.s1','材料测试','The engineer heated the polymer gently to elongate the sample, then measured how far it stretched before beginning to thin.','工程师轻微加热聚合物以拉长样品，随后测量它开始变薄前延伸了多远。','The engineer heated the polymer gently / to elongate the sample / then measured how far it stretched / before beginning to thin.','elongate 作不定式动词，宾语是 sample；to 表示加热的目的。','拉伸样品使其变长，体现 elongate.s1 动词义。'),'The technician elongated the wire by compressing it until it became shorter.','The technician shortened the wire by compressing it until it became shorter.','压缩使线变短，不能称为拉长。','meaning',[q('elongate',1,1,'To elongate a wire is to?',['make it longer','make it heavier without changing length','turn it into a liquid'],'make it longer','elongate.s1 作动词表示拉长。'),q('elongate',2,2,'An elongate leaf is?',['long in relation to its width','perfectly round and flat','shorter than it is wide'],'long in relation to its width','elongate.s2 作形容词表示细长。'),q('elongate',3,1,'Which action might elongate a piece of soft dough?',['pulling it gently at both ends','pressing it into a smaller ball','cutting it into squares'],'pulling it gently at both ends','两端拉伸可使面团变长。'),q('elongate',4,1,'Elongate is related to which adjective?',['long','electric','eligible'],'long','elongate 与 long“长”有词源联系。')]);

put('elongated','elongated 是 elongate 的过去分词形容词，表示被拉长的或形状异常细长的；其词根与拉丁语 longus“长”相关。',c('elongated.s1','医学影像','The scan showed an elongated shadow near the rib, so the radiologist requested another view before drawing a conclusion.','扫描图显示肋骨附近有一道细长阴影，因此放射科医生在下结论前要求补拍一个角度。','The scan showed an elongated shadow near the rib / so the radiologist requested another view / before drawing a conclusion.','elongated 修饰 shadow；so 引出为进一步判读而采取的措施。','影像中长度明显大于宽度的阴影是 elongated。'),'The scan showed an elongated mark shaped like a perfect circle with equal width and length.','The scan showed a round mark shaped like a perfect circle with equal width and length.','宽度和长度相等的圆形标记不属于细长形。','meaning',[q('elongated',1,1,'An elongated object is?',['stretched or unusually long','perfectly spherical','extremely short and wide'],'stretched or unusually long','elongated.s1 表示被拉长或细长的。'),q('elongated',2,1,'Which shape is elongated?',['a narrow oval much longer than it is wide','a small round coin','a square tile'],'a narrow oval much longer than it is wide','长度远大于宽度的椭圆呈细长形。'),q('elongated',3,1,'An elongated cell has likely?',['a long, narrow form','no measurable shape','the shape of a cube'],'a long, narrow form','生物学上 elongated 描述细长形态。'),q('elongated',4,1,'The word elongated is related to the verb?',['elongate','elect','elude'],'elongate','elongated 是 elongate 的分词形容词。')]);

put('eloquently','eloquently 由 eloquent 加副词后缀 -ly 构成；eloquent 源自拉丁语 eloqui“说出”，表示表达清楚流畅且有感染力地。',c('eloquently.s1','公开演讲','The witness spoke eloquently about the river’s decline, combining precise measurements with a vivid account of how it affected local families.','证人富有感染力地讲述河流的衰退，把精确测量数据与当地家庭受到影响的生动经历结合起来。','The witness spoke eloquently about the river’s decline / combining precise measurements / with a vivid account / of how it affected local families.','eloquently 修饰 spoke；combining 短语说明语言兼具数据与具体经历。','表达清晰有力且令人信服，体现 eloquently.s1。'),'The witness spoke eloquently by mumbling so unclearly that nobody could understand a word.','The witness spoke incoherently by mumbling so unclearly that nobody could understand a word.','无人听懂的含混表达不符合 eloquently 的清晰有力。','meaning',[q('eloquently',1,1,'To speak eloquently is to speak?',['clearly and persuasively','in a way nobody can follow','without using any language'],'clearly and persuasively','eloquently.s1 指清晰流畅且有感染力地表达。'),q('eloquently',2,1,'Which speaker communicates eloquently?',['one who presents a clear argument with memorable examples','one who mumbles unrelated fragments','one who refuses to explain the point'],'one who presents a clear argument with memorable examples','清晰论证和恰当例子体现表达力。'),q('eloquently',3,1,'A photograph may speak eloquently in a figurative sense if it?',['conveys a powerful message without many words','contains no visible subject or meaning','is silent because it is a photograph'],'conveys a powerful message without many words','比喻上，图像也能有力传达信息。'),q('eloquently',4,1,'Eloquently is the adverb form of?',['eloquent','elusive','elective'],'eloquent','eloquently 由形容词 eloquent 派生。')]);

put('elucidate','elucidate 源自拉丁语 elucidare“照亮、阐明”，由 ex- 与 lucidus“明亮的”相关；动词指把难点解释清楚。',c('elucidate.s1','科学报告','The diagram helped elucidate the feedback loop by showing exactly where each signal entered and how it changed the next response.','这张图通过准确标出每个信号的输入位置及其如何改变下一次反应，帮助阐明了反馈回路。','The diagram helped elucidate the feedback loop / by showing exactly where each signal entered / and how it changed the next response.','elucidate 作 helped 的宾语补足动词；by 引出使概念清楚的方式。','图示说明输入与后续反应之间的联系，使复杂机制变清楚。'),'The diagram elucidated the mechanism by removing every label and hiding the direction of each signal.','The diagram obscured the mechanism by removing every label and hiding the direction of each signal.','删去标签并隐藏信号方向会使机制更难理解，属于 obscuring。','meaning',[q('elucidate',1,1,'To elucidate a difficult point is to?',['explain it clearly','make it more confusing','leave it entirely unmentioned'],'explain it clearly','elucidate.s1 指阐明难点。'),q('elucidate',2,1,'Which tool could elucidate a complex process?',['a labeled diagram tracing each step','a blank page with no explanation','an unrelated list of names'],'a labeled diagram tracing each step','标注清晰的流程图可帮助解释复杂过程。'),q('elucidate',3,1,'A witness may elucidate an event by?',['clarifying the sequence of what happened','concealing every relevant detail','changing the subject to lunch'],'clarifying the sequence of what happened','澄清事件经过就是使情况更明白。'),q('elucidate',4,1,'Elucidate is closest in meaning to?',['clarify','obscure','interrupt'],'clarify','elucidate 与 clarify 都表示阐明。')]);

put('elude','elude 源自拉丁语 eludere“逃避、躲过”，由 e-/ex-“离开”与 ludere“戏弄”相关；可指躲避追捕，也可指目标、理解或记忆总难以达到。',c('elude.s2','记忆与理解','The name of the composer eluded Priya during the quiz, although she could recall the melody and the year she first heard it.','测验时，普里娅怎么也想不起那位作曲家的名字，尽管她记得旋律和第一次听到它的年份。','The name of the composer eluded Priya during the quiz / although she could recall the melody / and the year she first heard it.','elude 以 Priya 为间接语义对象，name 作主语；although 对比记忆到的线索。','名字暂时无法被她想起，体现 elude.s2 的记忆义。'),'The key to the cipher eluded the team even though they had already understood and solved it.','The key to the cipher did not elude the team; they had already understood and solved it.','If a solution eludes someone, that person has not yet found or understood it.','meaning',[q('elude',1,1,'A fugitive who eludes the police manages to?',['avoid being caught','ask them for directions','join their patrol'],'avoid being caught','elude.s1 指躲开追捕或发现。'),q('elude',2,2,'If a word eludes your memory, you?',['cannot recall it at that moment','have written it clearly on the page','have just learned to pronounce it'],'cannot recall it at that moment','elude.s2 可指使人想不起来。'),q('elude',3,2,'A solution that eludes researchers has?',['not yet been found or understood by them','already been explained completely','been printed in every report'],'not yet been found or understood by them','目标难以达到或理解也可说 elude。'),q('elude',4,1,'Which animal eluded the tracker?',['one that escaped without being found','one that waited beside the tracker','one that was drawn on a map'],'one that escaped without being found','躲开追踪者符合 elude.s1。')]);

})();
